// ============================================================
// 🗺️ ActiveRideOverlay.jsx — Navigation-Mode Map Overlay
//
// This is the full-screen Google Maps-style navigation experience
// shown when a ride is in progress. Covers the entire viewport.
//
// ── FEATURES ──────────────────────────────────────────────
//   ✅ Full-screen MapLibre map with OSM tiles
//   ✅ Live GPS tracking — blue pulsing BEARING ARROW moves + rotates
//   ✅ Dynamic blue route line — shrinks as user progresses
//   ✅ NEXT MANEUVER BAR — Google Maps-style top instruction banner
//      showing the current turn instruction + distance to it
//   ✅ SPEED DISPLAY — current speed in km/h (bottom-left HUD chip)
//   ✅ DIRECTIONS PANEL — tap list icon to see all route steps
//      with the active step highlighted and auto-scrolled into view
//   ✅ Minimize button — shrinks to a floating widget
//   ✅ Close button — hides the map, ride stays alive
//   ✅ End Ride button — permanently ends the ride (two-click confirm)
//   ✅ Bottom bar: LIVE distance RIDDEN + remaining distance + ETA + total route
//   ✅ Live distance travelled — route-accurate (snap-to-route) with GPS noise
//      filtering; paused while minimized/backgrounded; saved on ride end
//   ✅ GPS error banner when location permission is denied
//   ✅ Camera-follow mode via RideMap's built-in follow logic
//   ✅ VIEW-ONLY MODE — for completed/cancelled rides (no End Ride button)
//
// ── PROPS ─────────────────────────────────────────────────
//   ride    — active ride object (from backend / localStorage)
//   onClose — called when X is pressed (hides overlay, ride stays active)
//   onEnd   — called when "End Ride" is confirmed
// ============================================================

import { useState, useEffect, useRef, useCallback } from "react";
import RideMap         from "./RideMap";
import DirectionsPanel from "./DirectionsPanel";
import { watchLocation } from "../../../services/locationService";
import {
  formatDistance,
  formatDuration,
  haversineDistance,
  findActiveStep,
} from "../../../services/routingApi";
import { updateUserLocation, getGroupRideParticipants, updateParticipantStatus } from "../../../services/rideApi";
import GroupRidersPanel from "./GroupRidersPanel";
import { useAuth } from "../../../context/AuthContext";
import { useRideDistance } from "../../hooks/useRideDistance";

const RIDER_COLORS = [
  "#8b5cf6", "#14b8a6", "#f59e0b", "#ec4899", "#06b6d4",
  "#10b981", "#f43f5e", "#6366f1", "#84cc16", "#e11d48",
];

// ── Parse steps — ride.routeSteps is stored as JSON string in DB ──
function parseSteps(ride) {
  if (!ride) return [];
  if (Array.isArray(ride.routeSteps)) return ride.routeSteps;
  if (typeof ride.routeSteps === "string") {
    try { return JSON.parse(ride.routeSteps); } catch { return []; }
  }
  return [];
}

export default function ActiveRideOverlay({ ride, onClose, onEnd, onLeave }) {
  // ── Live GPS state ──
  const [myLocation,    setMyLocation]   = useState(null);
  const [gpsError,      setGpsError]     = useState(null);

  // ── Live remaining stats ──
  const [remainingDist, setRemainingDist] = useState(null); // metres
  const [remainingTime, setRemainingTime] = useState(null); // seconds

  // ── Navigation step state ──
  const [steps,       setSteps]       = useState(() => parseSteps(ride));
  const [activeStep,  setActiveStep]  = useState(0);

  // ── UI state ──
  const [minimized,       setMinimized]       = useState(false);
  const [confirmEnd,      setConfirmEnd]       = useState(false);
  const [ending,          setEnding]           = useState(false);
  const [confirmLeave,    setConfirmLeave]     = useState(false);
  const [leaving,         setLeaving]          = useState(false);
  const [showDirections,  setShowDirections]   = useState(false);
  const [miniPosition,    setMiniPosition]     = useState(null);

  const [participants, setParticipants] = useState([]);
  const [participantLocations, setParticipantLocations] = useState({});

  const { user } = useAuth();

  const stopGpsRef = useRef(null);
  const miniDragRef = useRef({ pointerId: null, offsetX: 0, offsetY: 0, moved: false });

  // ── Determine if ride is active (live navigation) or view-only ──
  // Completed/cancelled rides open in view-only mode — no End Ride button,
  // no GPS tracking started (to avoid unnecessary battery drain).
  const isActiveRide = ride?.status === "active";

  // ====================================================================
  // ROLE DETECTION (group rides)
  // Admin = ride creator (ride.userId) OR a participant with role "admin".
  //   • Admin               → sees "End Ride" only
  //   • Non-admin member    → sees "Leave Ride" only
  //   • Solo rides          → unchanged (creator always sees "End Ride")
  // ====================================================================
  const isGroupRide = ride?.rideType === "group";
  const isAdmin = !isGroupRide
    ? true // solo rides preserve existing End Ride behavior
    : String(ride?.userId) === String(user?.id) ||
      participants.some(
        p => String(p.userId) === String(user?.id) && p.role === "admin"
      );
  const showEndRide   = isActiveRide && (!isGroupRide || isAdmin);
  const showLeaveRide = isActiveRide && !isAdmin && isGroupRide;

  // ====================================================================
  // LIVE DISTANCE TRAVELLED
  // Accurately accumulates how far the rider has ACTUALLY ridden:
  //   • route-accurate mode when the ride has a stored OSRM polyline
  //     (snap-to-route), straight-line haversine otherwise
  //   • GPS noise/jump filtering lives in services/rideTracking.js
  //   • paused while the overlay is minimized or the tab is backgrounded,
  //     re-anchoring on resume so skipped stretches are never counted
  //   • resets automatically when a different ride starts
  // ====================================================================
  const { distanceTraveled, usingRoute } = useRideDistance(myLocation, {
    routeCoordinates: ride?.routeCoordinates,
    rideId: ride?.id,
    paused: minimized || !isActiveRide,
  });

  // ====================================================================
  // PARTICIPANTS — initial fetch + live refresh
  // GET /api/rides/{id}/participants returns ACTIVE riders only, so
  // re-fetching automatically drops riders who left (their markers
  // disappear) and picks up riders the admin adds mid-ride.
  // Demo-dragged marker positions live in `participantLocations` (keyed
  // by userId) and are merged in at render time, so they survive polls.
  // ====================================================================
  const refreshParticipants = useCallback(() => {
    if (ride?.rideType === "group" && ride?.id) {
      getGroupRideParticipants(ride.id)
        .then(list => setParticipants(list || []))
        .catch(() => {});
    } else {
      setParticipants([]);
    }
  }, [ride?.id, ride?.rideType]);

  useEffect(() => {
    refreshParticipants();
  }, [refreshParticipants]);

  // Poll every 10s while the overlay shows a LIVE group ride so
  // added/left riders update without a manual refresh
  useEffect(() => {
    if (!isActiveRide || ride?.rideType !== "group" || !ride?.id) return;
    const interval = setInterval(refreshParticipants, 10000);
    return () => clearInterval(interval);
  }, [isActiveRide, ride?.id, ride?.rideType, refreshParticipants]);

  useEffect(() => {
    const handler = (e) => {
      const { userId, lat, lng } = e.detail;
      setParticipantLocations(prev => ({
        ...prev,
        [userId]: { lat, lng },
      }));
    };
    window.addEventListener("simulate-group-gps", handler);
    return () => window.removeEventListener("simulate-group-gps", handler);
  }, []);

  // Parse steps whenever ride changes
  useEffect(() => {
    setSteps(parseSteps(ride));
  }, [ride]);

  // ── Current step derived values ──
  const currentStep    = steps[activeStep];
  const nextStep       = steps[activeStep + 1];
  const isLastStep     = activeStep >= steps.length - 1;

  // ====================================================================
  // START GPS when overlay mounts (only for active rides); STOP on unmount
  // ====================================================================
  useEffect(() => {
    // Only track GPS for active rides — not for history view
    if (!isActiveRide) return;

    const stop = watchLocation(
      (loc) => {
        setMyLocation(loc);
        setGpsError(null);

        // ── Remaining distance + ETA ──
        if (ride?.destinationLat && ride?.destinationLng) {
          const distM = haversineDistance(
            loc.lat, loc.lng,
            ride.destinationLat, ride.destinationLng
          );
          setRemainingDist(distM);
          if (ride.distanceMeters > 0 && ride.durationSeconds > 0) {
            const avgSpeed   = ride.distanceMeters / ride.durationSeconds;
            setRemainingTime(distM / avgSpeed);
          }
        }

        // ── Find which navigation step is currently active ──
        setActiveStep(prev => {
          const steps = parseSteps(ride);
          if (!steps.length) return prev;
          const next = findActiveStep(steps, loc.lat, loc.lng);
          // Only advance forward — never go backward
          return next >= prev ? next : prev;
        });

        // ── Persist user position to backend ──
        if (ride?.id) {
          updateUserLocation(ride.id, loc.lat, loc.lng, user?.id).catch(err => {
            console.warn("[ActiveRideOverlay] location update failed:", err.message);
          });
        }
      },
      (err) => setGpsError(err.message)
    );

    stopGpsRef.current = stop;
    return () => stop();
  }, [isActiveRide]); // eslint-disable-line react-hooks/exhaustive-deps

  // ====================================================================
  // END RIDE handler (two-click confirm)
  // ====================================================================
  const handleEndRide = async () => {
    if (!confirmEnd) { setConfirmEnd(true); return; }
    setEnding(true);
    setConfirmEnd(false);
    // Stop GPS tracking before calling onEnd
    stopGpsRef.current?.();
    stopGpsRef.current = null;
    // Hand the real travelled distance to Home → PATCH /api/rides/{id}/status
    await onEnd({ distanceTraveled });
    setEnding(false);
  };

  const cancelEnd = () => setConfirmEnd(false);

  // ====================================================================
  // LEAVE RIDE handler (two-click confirm) — non-admin group members only
  // Stops GPS, marks this user as "left" on the backend, closes the
  // overlay and asks Home to refresh (ride itself stays active for
  // everyone else).
  // ====================================================================
  const handleLeaveRide = async () => {
    if (!confirmLeave) { setConfirmLeave(true); return; }
    setLeaving(true);
    setConfirmLeave(false);
    // Stop GPS tracking — leaving riders no longer share their location
    stopGpsRef.current?.();
    stopGpsRef.current = null;
    try {
      // PATCH /api/rides/{id}/participants/{userId}/status { status: "left", actorUserId }
      await updateParticipantStatus(ride.id, user?.id, "left", user?.id);
    } catch (err) {
      console.warn("[ActiveRideOverlay] leave ride failed:", err.message);
    }
    setLeaving(false);
    // Close overlay + refresh Home (falls back to onClose if no onLeave given)
    if (onLeave) onLeave();
    else onClose?.();
  };

  const cancelLeave = () => setConfirmLeave(false);

  // ── Derive current step distance (to next maneuver) ──
  const stepDist = currentStep?.distance || 0;

  // ── Minimized-map bubble: tap to restore, drag to reposition ──
  const handleMiniPointerDown = (event) => {
    const rect = event.currentTarget.getBoundingClientRect();
    miniDragRef.current = {
      pointerId: event.pointerId,
      offsetX: event.clientX - rect.left,
      offsetY: event.clientY - rect.top,
      moved: false,
    };
    event.currentTarget.setPointerCapture(event.pointerId);
  };

  const handleMiniPointerMove = (event) => {
    const drag = miniDragRef.current;
    if (drag.pointerId !== event.pointerId) return;

    // Bubble is 104 × 46 px (see the style below) — keep it inside the viewport
    const bubbleWidth  = 104;
    const bubbleHeight = 46;
    const left = Math.min(Math.max(10, event.clientX - drag.offsetX), window.innerWidth  - bubbleWidth  - 10);
    const top  = Math.min(Math.max(10, event.clientY - drag.offsetY), window.innerHeight - bubbleHeight - 10);
    drag.moved = true;
    setMiniPosition({ left, top });
  };

  const handleMiniPointerUp = (event) => {
    const drag = miniDragRef.current;
    if (drag.pointerId !== event.pointerId) return;
    event.currentTarget.releasePointerCapture?.(event.pointerId);
    miniDragRef.current.pointerId = null;
    if (!drag.moved) setMinimized(false);
  };

  // ====================================================================
  // MINIMIZED state — compact draggable map bubble
  // ====================================================================
  if (minimized) {
    return (
      <>
        <style>{`
          @keyframes miniMapPulse {
            0%, 100% { opacity: 1; transform: scale(1); }
            50%       { opacity: 0.55; transform: scale(1.4); }
          }
          @keyframes miniMapGlow {
            0%, 100% { box-shadow: 0 0 0 0px rgba(59,130,246,0.55), 0 8px 28px rgba(0,0,0,0.55); }
            50%       { box-shadow: 0 0 0 7px rgba(59,130,246,0.0),  0 8px 28px rgba(0,0,0,0.55); }
          }
          .mini-map-btn:hover {
            transform: scale(1.06) !important;
            filter: brightness(1.12);
          }
          .mini-map-btn:active {
            transform: scale(0.97) !important;
          }
        `}</style>

        <div
          className="mini-map-btn"
          style={{
            position:        "fixed",
            ...(miniPosition
              ? { left: `${miniPosition.left}px`, top: `${miniPosition.top}px` }
              : { right: "20px", bottom: "22px" }),
            zIndex:          9999,
            display:         "flex",
            alignItems:      "center",
            justifyContent:  "center",
            gap:             "7px",
            width:           "104px",
            height:          "46px",
            background:      "linear-gradient(135deg, #3b82f6 0%, #1d4ed8 60%, #1e3a8a 100%)",
            border:          "1.5px solid rgba(255,255,255,0.22)",
            borderRadius:    "999px",
            boxShadow:       "0 0 0 0px rgba(59,130,246,0.55), 0 8px 28px rgba(0,0,0,0.55)",
            animation:       "miniMapGlow 2.6s ease-in-out infinite",
            cursor:          "grab",
            touchAction:     "none",
            userSelect:      "none",
            transition:      "transform 0.18s ease, filter 0.18s ease",
            /* glass sheen */
            backdropFilter:  "blur(6px)",
            WebkitBackdropFilter: "blur(6px)",
            overflow:        "hidden",
          }}
          title="Drag to move · tap to reopen the map"
          onPointerDown={handleMiniPointerDown}
          onPointerMove={handleMiniPointerMove}
          onPointerUp={handleMiniPointerUp}
          onPointerCancel={handleMiniPointerUp}
        >
          {/* Top-left sheen highlight */}
          <div style={{
            position:     "absolute",
            top: 0, left: 0,
            width:        "60%",
            height:       "50%",
            background:   "linear-gradient(135deg, rgba(255,255,255,0.18) 0%, transparent 100%)",
            borderRadius: "999px 999px 60% 0",
            pointerEvents:"none",
          }} />

          {/* Live status dot */}
          <span style={{
            position:     "absolute",
            top:          "8px",
            right:        "9px",
            width:        "8px",
            height:       "8px",
            borderRadius: "50%",
            background:   isActiveRide ? "#4ade80" : "#6b7280",
            boxShadow:    isActiveRide ? "0 0 6px #4ade80" : "none",
            animation:    isActiveRide ? "miniMapPulse 2s ease-in-out infinite" : "none",
            border:       "1.5px solid rgba(255,255,255,0.6)",
          }} />

          {/* Map icon */}
          <i
            className="fa fa-map"
            style={{
              color:        "rgba(255,255,255,0.95)",
              fontSize:     "16px",
              pointerEvents:"none",
              filter:       "drop-shadow(0 1px 3px rgba(0,0,0,0.4))",
            }}
          />

          {/* Label + live ridden distance */}
          <span style={{
            display:       "flex",
            flexDirection: "column",
            alignItems:    "flex-start",
            lineHeight:    1.15,
            pointerEvents: "none",
            textShadow:    "0 1px 4px rgba(0,0,0,0.35)",
          }}>
            {distanceTraveled > 0 ? (
              <>
                <span style={{ color: "#bbf7d0", fontWeight: 900, fontSize: "13px", letterSpacing: "0.2px" }}>
                  {formatDistance(distanceTraveled)}
                </span>
                <span style={{ color: "rgba(255,255,255,0.75)", fontWeight: 600, fontSize: "8.5px", letterSpacing: "0.6px" }}>
                  RIDDEN
                </span>
              </>
            ) : (
              <span style={{ color: "rgba(255,255,255,0.95)", fontWeight: 700, fontSize: "13.5px", letterSpacing: "0.5px" }}>
                Map
              </span>
            )}
          </span>
        </div>
      </>
    );
  }

  // ====================================================================
  // FULL-SCREEN overlay
  // ====================================================================
  return (
    <div style={{
      position:      "fixed",
      inset:         0,
      zIndex:        999,
      display:       "flex",
      flexDirection: "column",
      background:    "#000",
    }}>

      {/* ============================================================
          NEXT MANEUVER BAR — Google Maps-style navigation instruction
          ============================================================ */}
      <div style={{
        position:       "absolute",
        top:            0, left: 0, right: 0,
        zIndex:         9999,
        padding:        "12px 16px 8px",
        background:     "linear-gradient(to bottom, rgba(0,0,0,0.88) 0%, transparent 100%)",
        pointerEvents:  "none",
      }}>
        {/* ── Row 1: Next turn instruction (only for active rides with steps) ── */}
        {currentStep && isActiveRide && (
          <div style={{
            display:        "flex",
            alignItems:     "center",
            gap:            "12px",
            background:     "rgba(15,15,26,0.42)",
            backdropFilter: "blur(26px)",
            border:         "1px solid rgba(255,255,255,0.08)",
            borderRadius:   "16px",
            padding:        "12px 16px",
            marginBottom:   "px",
            boxShadow:      "0 4px 24px rgba(0,0,0,0.5)",
            pointerEvents:  "auto",
          }}>

            {/* Maneuver icon circle */}
            <div style={{
              width:          "38px",
              height:         "38px",
              borderRadius:   "120px",
              background:     "linear-gradient(135deg, rgba(66,133,244,0.3), rgba(66,133,244,0.15))",
              border:         "1.5px solid rgba(66,133,244,0.4)",
              display:        "flex",
              alignItems:     "center",
              justifyContent: "center",
              flexShrink:     0,
            }}>
              <i
                className={`fa ${currentStep.icon}`}
                style={{ color: "#4285F4", fontSize: "20px" }}
              />
            </div>

            {/* Instruction text + distance */}
            <div style={{ flex: 1, minWidth: 0 }}>
              {/* Distance to next maneuver */}
              {stepDist > 0 && (
                <p style={{
                  color:      "#4285F4",
                  fontWeight: 900,
                  fontSize:   "13px",
                  margin:     "0 0 2px",
                  letterSpacing: "0.5px",
                }}>
                  in {formatDistance(stepDist)}
                </p>
              )}
              {/* Instruction */}
              <p style={{
                color:      "white",
                fontWeight: 700,
                fontSize:   "15px",
                margin:     0,
                lineHeight: "1.3",
                overflow:   "hidden",
                textOverflow:"ellipsis",
                display:    "-webkit-box",
                WebkitLineClamp: 2,
                WebkitBoxOrient: "vertical",
              }}>
                {currentStep.instruction}
              </p>
            </div>

            {/* Right: control buttons */}
            <div style={{ display: "flex", flexDirection: "row", gap: "6px", pointerEvents: "auto" }}>
              {/* Directions list toggle */}
              <button
                onClick={() => setShowDirections(v => !v)}
                title="Show all directions"
                style={{
                  width:          "36px",
                  height:         "36px",
                  borderRadius:   "10px",
                  background:     showDirections
                    ? "linear-gradient(135deg, rgba(249,115,22,0.3), rgba(236,72,153,0.2))"
                    : "rgba(255,255,255,0.08)",
                  border:         showDirections
                    ? "1px solid rgba(249,115,22,0.5)"
                    : "1px solid rgba(255,255,255,0.12)",
                  color:          showDirections ? "#f97316" : "white",
                  cursor:         "pointer",
                  display:        "flex",
                  alignItems:     "center",
                  justifyContent: "center",
                  fontSize:       "13px",
                  transition:     "background 0.2s, border 0.2s",
                }}
              >
                <i className="fa fa-list" />
              </button>
              {/* Minimize */}
              <button
                onClick={() => setMinimized(true)}
                title="Minimize"
                style={{
                  width:          "36px",
                  height:         "36px",
                  borderRadius:   "10px",
                  background:     "rgba(255,255,255,0.08)",
                  border:         "1px solid rgba(255,255,255,0.12)",
                  color:          "white",
                  cursor:         "pointer",
                  display:        "flex",
                  alignItems:     "center",
                  justifyContent: "center",
                  fontSize:       "12px",
                }}
              >
                <i className="fa fa-minus" />
              </button>
              {/* Close */}
              <button
                onClick={onClose}
                title="Close map"
                style={{
                  width:          "36px",
                  height:         "36px",
                  borderRadius:   "10px",
                  background:     "rgba(255,255,255,0.08)",
                  border:         "1px solid rgba(255,255,255,0.12)",
                  color:          "white",
                  cursor:         "pointer",
                  display:        "flex",
                  alignItems:     "center",
                  justifyContent: "center",
                  fontSize:       "13px",
                }}
              >
                <i className="fa fa-times" />
              </button>
            </div>
          </div>
        )}

        {/* ── If no steps yet or view-only mode — show compact top bar ── */}
        {(!currentStep || !isActiveRide) && (
          <div style={{
            display:        "flex",
            alignItems:     "center",
            justifyContent: "space-between",
            background:     "rgba(0,0,0,0.65)",
            backdropFilter: "blur(12px)",
            border:         "1px solid rgba(255,255,255,0.1)",
            borderRadius:   "50px",
            padding:        "8px 16px",
            pointerEvents:  "auto",
          }}>
            <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
              <span style={{
                width: "8px", height: "8px", borderRadius: "50%",
                background: isActiveRide ? "#22c55e" : "#9ca3af",
                animation: isActiveRide ? "pulse 2s ease-in-out infinite" : "none",
              }} />
              <span style={{ color: "white", fontWeight: 700, fontSize: "13px" }}>
                {(ride.fromName || "From").split(",")[0]} → {(ride.destinationName || "Destination").split(",")[0]}
              </span>
              {/* View-only badge for completed rides */}
              {!isActiveRide && (
                <span style={{
                  background: "rgba(156,163,175,0.2)",
                  border: "1px solid rgba(156,163,175,0.3)",
                  borderRadius: "50px",
                  padding: "2px 8px",
                  color: "#9ca3af",
                  fontSize: "10px",
                  fontWeight: 700,
                  textTransform: "uppercase",
                  letterSpacing: "0.5px",
                }}>
                  {ride.status || "Completed"}
                </span>
              )}
            </div>
            <div style={{ display: "flex", gap: "8px" }}>
              {steps.length > 0 && (
                <button onClick={() => setShowDirections(v => !v)} style={topBtnStyle}>
                  <i className="fa fa-list" />
                </button>
              )}
              <button onClick={() => setMinimized(true)} style={topBtnStyle}>
                <i className="fa fa-minus" />
              </button>
              <button onClick={onClose} style={topBtnStyle}>
                <i className="fa fa-times" />
              </button>
            </div>
          </div>
        )}
      </div>

      {/* ============================================================
          MAP CANVAS
          ============================================================ */}
      <div style={{ flex: 1, position: "relative", height: 0, overflow: "hidden" }}>
        {(() => {
          const participantsWithLocations = participants.map((p, i) => ({
            ...p,
            lat: participantLocations[p.userId]?.lat || (ride?.fromLat ? ride.fromLat + (i + 1) * 0.003 : null),
            lng: participantLocations[p.userId]?.lng || (ride?.fromLng ? ride.fromLng + (i + 1) * 0.003 : null),
            color: RIDER_COLORS[i % RIDER_COLORS.length],
          }));

          return (
            <>
              <RideMap
                ride={ride}
                myLocation={myLocation}
                isLive={isActiveRide}
                participants={ride?.rideType === "group" ? participantsWithLocations : []}
                currentUserId={user?.id}
              />

              {ride?.rideType === "group" && participantsWithLocations.length > 0 && (
                <GroupRidersPanel
                  participants={participantsWithLocations}
                  currentUserId={user?.id}
                  isAdmin={isAdmin}
                  rideId={isActiveRide ? ride?.id : null}
                  onParticipantsChanged={refreshParticipants}
                  onRiderClick={(p) => {
                    if (p.lat && p.lng) {
                      window.dispatchEvent(new CustomEvent("rw-recenter", {
                        detail: { lat: p.lat, lng: p.lng }
                      }));
                    }
                  }}
                />
              )}
            </>
          );
        })()}

        {/* GPS error banner */}
        {gpsError && isActiveRide && (
          <div style={{
            position:       "absolute",
            top:            "160px",
            left:           "50%",
            transform:      "translateX(-50%)",
            background:     "rgba(239,68,68,0.92)",
            color:          "white",
            padding:        "8px 16px",
            borderRadius:   "10px",
            fontSize:       "12px",
            backdropFilter: "blur(8px)",
            whiteSpace:     "nowrap",
            zIndex:         20,
            boxShadow:      "0 4px 16px rgba(239,68,68,0.4)",
          }}>
            <i className="fa fa-triangle-exclamation" style={{ marginRight: "6px" }} />
            GPS: {gpsError}
          </div>
        )}
        
        {/* ── Speed HUD chip (bottom-left) — only during active rides ── */}
        {isActiveRide && myLocation?.speed != null && myLocation.speed >= 0 && (
          <div style={{
            position:       "absolute",
            bottom:         "200px",
            right:           "16px",
            zIndex:         9999,
            background:     "rgba(15,15,26,0.9)",
            backdropFilter: "blur(12px)",
            border:         "1px solid rgba(255,255,255,0.1)",
            borderRadius:   "14px",
            padding:        "8px 10px",
            textAlign:      "center",
            minWidth:       "30px",
          }}>
            <p style={{ color: "white", fontWeight: 900, fontSize: "20px", margin: 0, lineHeight: 1 }}>
             {Math.round(myLocation.speed * 3.6)}
            </p>
            <p style={{ color: "rgba(255,255,255,0.4)", fontSize: "9px", margin: "3px 0 0", textTransform: "uppercase", letterSpacing: "1px" }}>
              km/h
            </p>
          </div>
        )}

        {/* ── Step progress indicator (bottom-right) ── */}
        {steps.length > 0 && isActiveRide && (
          <div style={{
            position:       "absolute",
            bottom:         "120px",
            right:          "16px",
            zIndex:         9999,
            background:     "rgba(15,15,26,0.9)",
            backdropFilter: "blur(12px)",
            border:         "1px solid rgba(255,255,255,0.1)",
            borderRadius:   "140px",
            padding:        "10px 14px",
            textAlign:      "center",
            minWidth:       "60px",
          }}>
            <p style={{ color: "#4285F4", fontWeight: 900, fontSize: "16px", margin: 0, lineHeight: 1 }}>
              {activeStep + 1}/{steps.length}
            </p>
            <p style={{ color: "rgba(255,255,255,0.4)", fontSize: "9px", margin: "3px 0 0", textTransform: "uppercase", letterSpacing: "1px" }}>
              Steps
            </p>
          </div>
        )}
      </div>

      {/* ============================================================
          BOTTOM BAR — live stats + End Ride button
          ============================================================ */}
      <div style={{
        position:   "absolute",
        bottom:     0, left: 0, right: 0,
        zIndex:     999,
        background: "linear-gradient(to top, rgba(0,0,0,0.95) 0%, rgba(0,0,0,0.8) 60%, transparent 100%)",
        padding:    "10px 6px 4px",
      }}>

        {/* ── Stats row ── */}
        <div style={{
          display:        "flex",
          alignItems:     "center",
          justifyContent: "center",
          gap:            "14px",
          marginBottom:   "10px",
        }}>
          {/* Ridden so far — live, route-accurate when a route is stored */}
          <div style={{ flex: 1, textAlign: "center" }}>
            <p style={{ color: "#34d399", fontWeight: 900, fontSize: "19px", margin: 0 }}>
              {formatDistance(distanceTraveled)}
            </p>
            <p style={{ color: "rgba(255,255,255,0.45)", fontSize: "10px", margin: 0, textTransform: "uppercase", letterSpacing: "1px" }}>
              Ridden
            </p>
          </div>

          <div style={{ width: "1px", height: "32px", background: "rgba(255,255,255,0.12)" }} />

          {/* Remaining Distance */}
          <div style={{ flex: 1, textAlign: "center" }}>
            <p style={{ color: "#4285F4", fontWeight: 900, fontSize: "19px", margin: 0 }}>
              {remainingDist != null
                ? formatDistance(remainingDist)
                : formatDistance(ride.distanceMeters)}
            </p>
            <p style={{ color: "rgba(255,255,255,0.45)", fontSize: "10px", margin: 0, textTransform: "uppercase", letterSpacing: "1px" }}>
              {remainingDist != null ? "Remaining" : "Distance"}
            </p>
          </div>

          <div style={{ width: "1px", height: "32px", background: "rgba(255,255,255,0.12)" }} />

          {/* ETA */}
          <div style={{ flex: 1, textAlign: "center" }}>
            <p style={{ color: "white", fontWeight: 900, fontSize: "19px", margin: 0 }}>
              {remainingTime != null
                ? formatDuration(remainingTime)
                : formatDuration(ride.durationSeconds)}
            </p>
            <p style={{ color: "rgba(255,255,255,0.45)", fontSize: "10px", margin: 0, textTransform: "uppercase", letterSpacing: "1px" }}>
              ETA
            </p>
          </div>

          <div style={{ width: "1px", height: "32px", background: "rgba(255,255,255,0.12)" }} />

          {/* Ride type */}
          <div style={{ flex: 1, textAlign: "center" }}>
            <p style={{ color: "white", fontWeight: 900, fontSize: "22px", margin: 0 }}>
              {ride.rideType === "solo" ? "🏍️" : `👥 ${participants.length}`}
            </p>
            <p style={{ color: "rgba(255,255,255,0.45)", fontSize: "10px", margin: 0, textTransform: "uppercase", letterSpacing: "1px" }}>
              {ride.rideType === "solo" ? "solo" : "riders"}
            </p>
          </div>
        </div>

        {/* ── Total route meta line ── */}
        <p style={{
          textAlign:     "center",
          margin:        "0 0 8px",
          fontSize:      "10.5px",
          color:         "rgba(255,255,255,0.5)",
          letterSpacing: "0.3px",
        }}>
          Total route {formatDistance(ride.distanceMeters)} · {formatDuration(ride.durationSeconds)}
          {usingRoute && <span style={{ color: "#34d399" }}> · route-accurate</span>}
        </p>

        {/* ── Action button — only for ACTIVE rides ── */}
        {/* Admin/solo: End Ride · Non-admin group member: Leave Ride */}
        {/* BUG FIX: completed/cancelled rides show a "Close" button instead */}
        {isActiveRide ? (
          showLeaveRide ? (
            // ── LEAVE RIDE (non-admin group member, two-click confirm) ──
            confirmLeave ? (
              <div style={{ display: "flex", gap: "8px" }}>
                <button
                  onClick={cancelLeave}
                  style={{
                    flex: 1, padding: "14px",
                    background:   "rgba(255,255,255,0.1)",
                    border:       "1px solid rgba(255,255,255,0.1)",
                    borderRadius: "14px",
                    color:        "white",
                    fontWeight:   700,
                    fontSize:     "14px",
                    cursor:       "pointer",
                  }}
                >
                  <i className="fa fa-arrow-left" style={{ marginRight: "8px" }} />
                  Stay
                </button>
                <button
                  onClick={handleLeaveRide}
                  disabled={leaving}
                  style={{
                    flex: 1, padding: "14px",
                    background:   "linear-gradient(135deg, #f97316, #ea580c)",
                    border:       "none",
                    borderRadius: "14px",
                    color:        "white",
                    fontWeight:   900,
                    fontSize:     "14px",
                    cursor:       leaving ? "not-allowed" : "pointer",
                    opacity:      leaving ? 0.7 : 1,
                    boxShadow:    "0 4px 20px rgba(249,115,22,0.4)",
                  }}
                >
                  {leaving
                    ? <><i className="fa fa-spinner fa-spin" style={{ marginRight: "8px" }} />Leaving...</>
                    : <><i className="fa fa-person-walking-arrow-right" style={{ marginRight: "8px" }} />Confirm Leave</>
                  }
                </button>
              </div>
            ) : (
              <button
                onClick={handleLeaveRide}
                style={{
                  width:          "100%",
                  padding:        "15px",
                  background:     "rgba(249,115,22,0.15)",
                  border:         "1.5px solid rgba(249,115,22,0.5)",
                  borderRadius:   "14px",
                  color:          "#fb923c",
                  fontWeight:     900,
                  fontSize:       "15px",
                  cursor:         "pointer",
                  backdropFilter: "blur(8px)",
                }}
              >
                <i className="fa fa-person-walking-arrow-right" style={{ marginRight: "8px" }} />
                Leave Ride
              </button>
            )
          ) : showEndRide ? (
          // ── END RIDE (admin / solo, two-click confirm) ──
          confirmEnd ? (
            <div style={{ display: "flex", gap: "8px" }}>
              <button
                onClick={cancelEnd}
                style={{
                  flex: 1, padding: "14px",
                  background:   "rgba(255,255,255,0.1)",
                  border:       "1px solid rgba(255,255,255,0.1)",
                  borderRadius: "14px",
                  color:        "white",
                  fontWeight:   700,
                  fontSize:     "14px",
                  cursor:       "pointer",
                }}
              >
                <i className="fa fa-arrow-left" style={{ marginRight: "8px" }} />
                Cancel
              </button>
              <button
                onClick={handleEndRide}
                disabled={ending}
                style={{
                  flex: 1, padding: "14px",
                  background:   "linear-gradient(135deg, #ef4444, #dc2626)",
                  border:       "none",
                  borderRadius: "14px",
                  color:        "white",
                  fontWeight:   900,
                  fontSize:     "14px",
                  cursor:       ending ? "not-allowed" : "pointer",
                  opacity:      ending ? 0.7 : 1,
                  boxShadow:    "0 4px 20px rgba(239,68,68,0.4)",
                }}
              >
                {ending
                  ? <><i className="fa fa-spinner fa-spin" style={{ marginRight: "8px" }} />Ending...</>
                  : <><i className="fa fa-flag-checkered" style={{ marginRight: "8px" }} />Confirm End</>
                }
              </button>
            </div>
          ) : (
            <button
              onClick={handleEndRide}
              style={{
                width:          "100%",
                padding:        "15px",
                background:     "rgba(239,68,68,0.15)",
                border:         "1.5px solid rgba(239,68,68,0.5)",
                borderRadius:   "14px",
                color:          "#ef4444",
                fontWeight:     900,
                fontSize:       "15px",
                cursor:         "pointer",
                backdropFilter: "blur(8px)",
              }}
            >
              <i className="fa fa-flag-checkered" style={{ marginRight: "8px" }} />
              End Ride
            </button>
          )
          ) : null
        ) : (
          // View-only mode for completed/cancelled rides
          <button
            onClick={onClose}
            style={{
              width:          "100%",
              padding:        "15px",
              background:     "rgba(255,255,255,0.08)",
              border:         "1.5px solid rgba(255,255,255,0.15)",
              borderRadius:   "14px",
              color:          "rgba(255,255,255,0.8)",
              fontWeight:     900,
              fontSize:       "15px",
              cursor:         "pointer",
              backdropFilter: "blur(8px)",
            }}
          >
            <i className="fa fa-times" style={{ marginRight: "8px" }} />
            Close
          </button>
        )}
      </div>

      {/* ============================================================
          DIRECTIONS PANEL — slide-up drawer with all steps
          ============================================================ */}
      {showDirections && (
        <DirectionsPanel
          steps={steps}
          activeStep={activeStep}
          onClose={() => setShowDirections(false)}
          totalDist={ride.distanceMeters}
          totalTime={ride.durationSeconds}
          destName={(ride.destinationName || "Destination").split(",")[0]}
        />
      )}

      <style>{`
        @keyframes pulse { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:0.5;transform:scale(1.4)} }
      `}</style>
    </div>
  );
}

// ── Shared small top-bar button style ──
const topBtnStyle = {
  width:          "36px",
  height:         "36px",
  borderRadius:   "50%",
  background:     "rgba(0,0,0,0.6)",
  backdropFilter: "blur(12px)",
  border:         "1px solid rgba(255,255,255,0.15)",
  color:          "red",
  cursor:         "pointer",
  display:        "flex",
  alignItems:     "center",
  justifyContent: "center",
  fontSize:       "14px",
};

// ============================================================
// 📋 RideHistoryPanel.jsx — Full ride history side panel
//
// Shows all rides for the logged-in user (newest first).
// Features per card:
//   ✅ From → Destination summary
//   ✅ Distance, duration, date
//   ✅ Status badge (active / completed / cancelled)
//   ✅ "Open Map" button — reopens the full-screen map for that ride
//   ✅ Delete button   — permanently deletes the ride after confirmation
//
// PROPS:
//   rides         — array of ride objects (from backend/localStorage)
//   onOpenRide    — callback(ride) — reopens full-screen map for a ride
//   onDeleteRide  — callback(rideId) — deletes ride + refreshes list
//   onClose       — close the panel
//   tc            — theme classes
// ============================================================

import { useState } from "react";
import RideMap from "./RideMap";
import { formatDistance, formatDuration } from "../../../services/routingApi";

// ---- Status → colour mapping ----
const STATUS_STYLE = {
  active:    { bg: "#22c55e22", border: "#22c55e44", text: "#22c55e" },
  completed: { bg: "#6b728022", border: "#6b728044", text: "#9ca3af" },
  cancelled: { bg: "#ef444422", border: "#ef444444", text: "#ef4444" },
};

export default function RideHistoryPanel({ rides, onOpenRide, onDeleteRide, onClose, tc }) {
  // Track which card's map is expanded
  const [expandedId, setExpandedId]   = useState(null);
  // Track which card has a delete confirmation pending
  const [deletingId,  setDeletingId]  = useState(null);
  const [deleting,    setDeleting]    = useState(false); // spinner state

  // Toggle a card's map expansion
  const toggleExpand = (id) => setExpandedId(prev => prev === id ? null : id);

  // First click on delete = show confirmation
  // Second click = actually delete
  const handleDelete = async (rideId) => {
    if (deletingId !== rideId) {
      setDeletingId(rideId); // show confirm state
      return;
    }
    setDeleting(true);
    await onDeleteRide(rideId);
    setDeletingId(null);
    setDeleting(false);
  };

  // Cancel the delete confirmation
  const cancelDelete = (e) => {
    e.stopPropagation(); // don't bubble to card expansion
    setDeletingId(null);
  };

  return (
    <div style={{
      position:       "fixed",
      inset:          0,
      zIndex:         7000,
      background:     "rgba(0,0,0,0.75)",
      backdropFilter: "blur(8px)",
      display:        "flex",
      justifyContent: "flex-end",  // panel slides in from the right
    }}
      onClick={e => { if (e.target === e.currentTarget) onClose(); }}
    >
      {/* ---- Side panel ---- */}
      <div style={{
        width:         "100%",
        maxWidth:      "480px",
        height:        "100%",
        background:    "linear-gradient(135deg, rgba(8,8,12,0.99), rgba(12,12,20,0.99))",
        backdropFilter:"blur(24px)",
        borderLeft:    "1px solid rgba(255,255,255,0.07)",
        display:       "flex",
        flexDirection: "column",
        animation:     "slideRight 0.3s cubic-bezier(0.32,0.72,0,1)",
        boxShadow:     "-20px 0 80px rgba(0,0,0,0.6)",
      }}>
        {/* ---- Header ---- */}
        <div style={{
          display:       "flex",
          alignItems:    "center",
          justifyContent:"space-between",
          padding:       "20px",
          borderBottom:  "1px solid rgba(255,255,255,0.06)",
          flexShrink:    0,
        }}>
          <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
            <div style={{
              width: "38px", height: "38px", borderRadius: "12px",
              background: "rgba(249,115,22,0.15)",
              border: "1px solid rgba(249,115,22,0.25)",
              display: "flex", alignItems: "center", justifyContent: "center",
            }}>
              <i className="fa fa-clock-rotate-left" style={{ color: "#f97316", fontSize: "16px" }} />
            </div>
            <div>
              <p style={{ fontWeight: 900, fontSize: "16px", margin: 0 }}>Ride History</p>
              <p style={{ fontSize: "11px", color: "rgba(255,255,255,0.35)", margin: 0 }}>
                {rides.length} ride{rides.length !== 1 ? "s" : ""} total
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            style={{
              width: "36px", height: "36px", borderRadius: "50%",
              background: "rgba(255,255,255,0.06)",
              border: "1px solid rgba(255,255,255,0.1)",
              color: "rgba(255,255,255,0.6)", cursor: "pointer",
              display: "flex", alignItems: "center", justifyContent: "center",
            }}
          >
            <i className="fa fa-times" />
          </button>
        </div>

        {/* ---- Ride list (scrollable) ---- */}
        <div style={{ overflowY: "auto", flex: 1, padding: "16px" }}>
          {rides.length === 0 ? (
            // Empty state
            <div style={{ textAlign: "center", padding: "60px 0" }}>
              <i className="fa fa-route" style={{ fontSize: "48px", color: "rgba(255,255,255,0.15)", display: "block", marginBottom: "16px" }} />
              <p style={{ fontWeight: 700, color: "rgba(255,255,255,0.4)", margin: "0 0 6px" }}>No rides yet</p>
              <p style={{ fontSize: "12px", color: "rgba(255,255,255,0.25)", margin: 0 }}>
                Start your first ride and it will appear here.
              </p>
            </div>
          ) : (
            // Ride cards
            rides.map(ride => {
              const statusStyle = STATUS_STYLE[ride.status] || STATUS_STYLE.completed;
              const isExpanded  = expandedId === String(ride.id);
              const isDeleting  = deletingId === String(ride.id);
              const dateStr     = ride.createdAt
                ? new Date(ride.createdAt).toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" })
                : "";

              return (
                <div
                  key={ride.id}
                  style={{
                    marginBottom:  "12px",
                    borderRadius:  "18px",
                    border:        "1px solid rgba(255,255,255,0.07)",
                    background:    "rgba(255,255,255,0.025)",
                    overflow:      "hidden",
                    transition:    "border-color 0.2s",
                  }}
                  onMouseEnter={e => e.currentTarget.style.borderColor = "rgba(255,255,255,0.13)"}
                  onMouseLeave={e => e.currentTarget.style.borderColor = "rgba(255,255,255,0.07)"}
                >
                  {/* Card header (always visible) */}
                  <div style={{ padding: "14px 16px" }}>
                    {/* From → Destination */}
                    <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: "8px", marginBottom: "10px" }}>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <p style={{ fontWeight: 700, fontSize: "14px", margin: "0 0 2px", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                          <i className="fa fa-circle" style={{ color: "#22c55e", fontSize: "7px", marginRight: "6px" }} />
                          {(ride.fromName || "From").split(",")[0]}
                        </p>
                        <p style={{ fontWeight: 700, fontSize: "14px", margin: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                          <i className="fa fa-circle" style={{ color: "#ef4444", fontSize: "7px", marginRight: "6px" }} />
                          {(ride.destinationName || "Destination").split(",")[0]}
                        </p>
                      </div>
                      {/* Status badge */}
                      <span style={{
                        padding: "3px 10px", borderRadius: "50px",
                        background: statusStyle.bg, border: `1px solid ${statusStyle.border}`,
                        color: statusStyle.text, fontSize: "10px", fontWeight: 700,
                        textTransform: "uppercase", letterSpacing: "0.5px", flexShrink: 0,
                      }}>
                        {ride.status}
                      </span>
                    </div>

                    {/* Meta row: distance · duration · date */}
                    <div style={{
                      display: "flex", alignItems: "center", gap: "8px",
                      fontSize: "11px", color: "rgba(255,255,255,0.35)", flexWrap: "wrap",
                    }}>
                      {ride.actualDistanceMeters > 0 && (
                        <>
                          <span title="Distance actually ridden">
                            <i className="fa fa-location-arrow" style={{ marginRight: "4px", color: "#34d399" }} />
                            {formatDistance(ride.actualDistanceMeters)} ridden
                          </span>
                          <span>·</span>
                        </>
                      )}
                      {ride.distanceMeters && (
                        <>
                          <span title="Planned route length"><i className="fa fa-route" style={{ marginRight: "4px", color: "#f97316" }} />{formatDistance(ride.distanceMeters)}</span>
                          <span>·</span>
                        </>
                      )}
                      {ride.durationSeconds && (
                        <>
                          <span><i className="fa fa-clock" style={{ marginRight: "4px" }} />{formatDuration(ride.durationSeconds)}</span>
                          <span>·</span>
                        </>
                      )}
                      {dateStr && <span>{dateStr}</span>}
                    </div>

                    {/* Action buttons row */}
                    <div style={{ display: "flex", gap: "8px", marginTop: "12px" }}>
                      {/* Open Map button */}
                      <button
                        onClick={() => onOpenRide(ride)}
                        style={{
                          flex: 1, padding: "8px 12px",
                          background: ride.status === "active"
                            ? "linear-gradient(135deg, #f97316, #ec4899)"
                            : "rgba(255,255,255,0.06)",
                          border: ride.status === "active" ? "none" : "1px solid rgba(255,255,255,0.1)",
                          borderRadius: "10px",
                          color: "white", fontWeight: 700, fontSize: "12px",
                          cursor: "pointer",
                          display: "flex", alignItems: "center", justifyContent: "center", gap: "6px",
                        }}
                      >
                        <i className={`fa ${ride.status === "active" ? "fa-location-crosshairs" : "fa-map"}`} />
                        {ride.status === "active" ? "Live Map" : "View Route"}
                      </button>

                      {/* Expand/collapse mini map */}
                      {ride.routeCoordinates && (
                        <button
                          onClick={() => toggleExpand(String(ride.id))}
                          style={{
                            padding: "8px 12px",
                            background: isExpanded ? "rgba(249,115,22,0.15)" : "rgba(255,255,255,0.05)",
                            border: `1px solid ${isExpanded ? "rgba(249,115,22,0.3)" : "rgba(255,255,255,0.1)"}`,
                            borderRadius: "10px",
                            color: isExpanded ? "#f97316" : "rgba(255,255,255,0.5)",
                            cursor: "pointer", fontSize: "12px",
                          }}
                          title={isExpanded ? "Collapse map" : "Preview route"}
                        >
                          <i className={`fa fa-chevron-${isExpanded ? "up" : "down"}`} />
                        </button>
                      )}

                      {/* Delete button (with confirmation) */}
                      {isDeleting ? (
                        // Confirmation row
                        <div style={{ display: "flex", gap: "6px" }}>
                          <button
                            onClick={cancelDelete}
                            style={{
                              padding: "8px 10px", borderRadius: "10px",
                              background: "rgba(255,255,255,0.06)",
                              border: "1px solid rgba(255,255,255,0.1)",
                              color: "white", cursor: "pointer", fontSize: "11px",
                            }}
                          >
                            <i className="fa fa-times" />
                          </button>
                          <button
                            onClick={() => handleDelete(String(ride.id))}
                            disabled={deleting}
                            style={{
                              padding: "8px 10px", borderRadius: "10px",
                              background: "rgba(239,68,68,0.2)",
                              border: "1px solid rgba(239,68,68,0.4)",
                              color: "#ef4444", cursor: deleting ? "not-allowed" : "pointer", fontSize: "11px",
                            }}
                          >
                            <i className={`fa ${deleting ? "fa-spinner fa-spin" : "fa-check"}`} />
                          </button>
                        </div>
                      ) : (
                        <button
                          onClick={() => handleDelete(String(ride.id))}
                          title="Delete ride"
                          style={{
                            padding: "8px 12px", borderRadius: "10px",
                            background: "rgba(239,68,68,0.06)",
                            border: "1px solid rgba(239,68,68,0.15)",
                            color: "rgba(239,68,68,0.6)",
                            cursor: "pointer", fontSize: "12px",
                          }}
                        >
                          <i className="fa fa-trash" />
                        </button>
                      )}
                    </div>
                  </div>

                  {/* Expandable mini map */}
                  {isExpanded && (
                    <div style={{ borderTop: "1px solid rgba(255,255,255,0.06)", height: "200px" }}>
                      <RideMap ride={ride} isLive={false} />
                    </div>
                  )}
                </div>
              );
            })
          )}
        </div>
      </div>

      {/* Slide-in animation keyframe */}
      <style>{`
        @keyframes slideRight {
          from { transform: translateX(100%); }
          to   { transform: translateX(0); }
        }
      `}</style>
    </div>
  );
}

// ============================================================
// RideMap.jsx — Leaflet Map (react-leaflet)
//
//   • MapContainer + TileLayer  → renders the map tiles
//   • DynamicRouteLine          → draws the road-following polyline from
//                                 stored OSRM coordinates; trims behind GPS
//   • L.Marker                  → A (start) and B (destination) pins
//   • Live GPS dot              → updates as myLocation changes
//   • Tile switcher overlay     → change map style at runtime
// ============================================================

import { useEffect, useRef, useState } from "react";
import { MapContainer, TileLayer, useMap } from "react-leaflet";
import L from "leaflet";
import "leaflet/dist/leaflet.css";
// NOTE: leaflet-routing-machine intentionally removed.
// We draw polylines directly from stored OSRM coordinates (DynamicRouteLine)
// so we don't need the routing-machine library at all.

// Fix Leaflet marker icon (broken in Vite — same fix as demo)
import markerIconPng   from "leaflet/dist/images/marker-icon.png";
import markerShadowPng from "leaflet/dist/images/marker-shadow.png";

delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconUrl:       markerIconPng,
  shadowUrl:     markerShadowPng,
  iconRetinaUrl: markerIconPng,
});

// ---------------------------------------------------------------------------
// Tile options (same as demo's MapTilesContainer)
// ---------------------------------------------------------------------------
const TILE_LAYERS = [
  { label: "🗺️ Default",   url: "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", attr: "© OpenStreetMap" },
  { label: "🚴 Cycle",     url: "https://{s}.tile-cyclosm.openstreetmap.fr/cyclosm/{z}/{x}/{y}.png", attr: "© CyclOSM" },
  { label: "🌑 Dark",      url: "https://tiles.stadiamaps.com/tiles/alidade_smooth_dark/{z}/{x}/{y}{r}.png", attr: "© Stadia" },
  { label: "🛰️ Satellite", url: "https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}", attr: "© ArcGIS" },
  { label: "🏔️ Terrain",   url: "https://tiles.stadiamaps.com/tiles/stamen_terrain/{z}/{x}/{y}{r}.png", attr: "© Stadia" },
];

// ---------------------------------------------------------------------------
// Custom pin icons
// ---------------------------------------------------------------------------
const RIDER_COLORS = [
  "#8b5cf6", // purple
  "#14b8a6", // teal
  "#f59e0b", // amber
  "#ec4899", // pink
  "#06b6d4", // cyan
  "#10b981", // emerald
  "#f43f5e", // rose
  "#6366f1", // indigo
  "#84cc16", // lime
  "#e11d48", // crimson
];

function makeRiderIcon(color, letter, name) {
  return L.divIcon({
    className: "",
    html: `<div style="display:flex;flex-direction:column;align-items:center;filter:drop-shadow(0 4px 6px rgba(0,0,0,0.4))">
      <div style="position:relative;width:44px;height:44px;background:${color};border-radius:50%;border:2px solid #fff;display:flex;align-items:center;justify-content:center;box-shadow:0 0 0 0 ${color}66;animation:rw-rider-pulse 3s infinite">
        <span style="font-size:14px;font-weight:900;color:#fff;font-family:system-ui">${letter}</span>
      </div>
      <div style="margin-top:4px;background:rgba(0,0,0,0.6);padding:2px 6px;border-radius:4px;color:#fff;font-size:11px;font-family:system-ui;white-space:nowrap;text-shadow:0 1px 2px rgba(0,0,0,0.8)">
        ${name}
      </div>
    </div>`,
    iconSize:    [44, 60],
    iconAnchor:  [22, 30],
    popupAnchor: [0, -30],
  });
}

function makePinIcon(color, letter) {
  return L.divIcon({
    className: "",
    html: `<div style="width:36px;height:44px;display:flex;flex-direction:column;align-items:center;filter:drop-shadow(0 4px 10px ${color}88)">
      <div style="width:36px;height:36px;background:linear-gradient(145deg,${color},${color}cc);border-radius:50% 50% 50% 0;transform:rotate(-45deg);border:3px solid #fff;display:flex;align-items:center;justify-content:center;box-sizing:border-box">
        <span style="transform:rotate(45deg);font-size:14px;font-weight:900;color:#fff;line-height:1;font-family:system-ui">${letter}</span>
      </div>
    </div>`,
    iconSize:    [36, 44],
    iconAnchor:  [18, 44],
    popupAnchor: [0, -44],
  });
}

const ICON_A = makePinIcon("#22c55e", "A");
const ICON_B = makePinIcon("#ef4444", "B");

const GPS_ICON = L.divIcon({
  className: "",
  html: `<div style="position:relative;width:52px;height:52px;display:flex;align-items:center;justify-content:center">
    <div style="position:absolute;inset:0;border-radius:50%;background:rgba(66,133,244,0.2);animation:rw-pulse 2.2s ease-out infinite"></div>
    <div style="position:relative;z-index:2;width:20px;height:20px;background:linear-gradient(145deg,#60a5fa,#1d4ed8);border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(66,133,244,0.35),0 3px 12px rgba(66,133,244,0.75)"></div>
  </div>`,
  iconSize:    [52, 52],
  iconAnchor:  [26, 26],
  popupAnchor: [0, -28],
});

// Inject animation CSS
if (typeof document !== "undefined" && !document.getElementById("rw-leaflet-css")) {
  const s = document.createElement("style");
  s.id = "rw-leaflet-css";
  s.textContent = `
    @keyframes rw-pulse { 0%{transform:scale(0.85);opacity:0.9} 60%{transform:scale(2.6);opacity:0} 100%{transform:scale(0.85);opacity:0} }
    @keyframes rw-rider-pulse { 0%{box-shadow:0 0 0 0 rgba(255,255,255,0.4)} 70%{box-shadow:0 0 0 10px rgba(255,255,255,0)} 100%{box-shadow:0 0 0 0 rgba(255,255,255,0)} }
    .leaflet-container { width:100%; height:100%; }
    /* Hide Leaflet controls at the top */
    .leaflet-top { display: none !important; }
    /* Push Leaflet controls up so they don't hide under the bottom panel */
    .leaflet-bottom { bottom: 120px !important; }
    /* Make sure our custom overlay controls are always clickable and on top */
    .rw-custom-control { z-index: 9999 !important; pointer-events: auto !important; }
  `;
  document.head.appendChild(s);
}

// ===========================================================================
// DynamicRouteLine — Smart route drawing:
//   • ON-ROUTE  (within 300m of saved path) → trims polyline behind GPS
//   • OFF-ROUTE (more than 300m away)       → fetches fresh OSRM road route
//                                             from current GPS to destination
// ===========================================================================

// How far (metres) the GPS must be from the saved route before we reroute
const OFF_ROUTE_THRESHOLD_M = 300;
// Only call OSRM reroute again if GPS moved more than this since last call
const REROUTE_DEBOUNCE_M    = 150;
// OSRM endpoint (same as routingApi.js)
const OSRM_BASE = "https://router.project-osrm.org/route/v1/driving";

// Haversine distance in metres (self-contained — no external import needed)
function getDistance(lat1, lon1, lat2, lon2) {
  const R  = 6371e3;
  const p1 = lat1 * Math.PI / 180;
  const p2 = lat2 * Math.PI / 180;
  const dp = (lat2 - lat1) * Math.PI / 180;
  const dl = (lon2 - lon1) * Math.PI / 180;
  const a  = Math.sin(dp/2)**2 + Math.cos(p1)*Math.cos(p2)*Math.sin(dl/2)**2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}

// Draw (or redraw) a two-layer polyline (white outline + blue fill)
function drawPolyline(map, routeRef, coords) {
  if (routeRef.current) { map.removeLayer(routeRef.current); }
  const outline = L.polyline(coords, { color: "#ffffff", weight: 20, opacity: 0.9 });
  const inline  = L.polyline(coords, { color: "#4285F4", weight: 12, opacity: 1.0 });
  routeRef.current = L.layerGroup([outline, inline]).addTo(map);
}

function DynamicRouteLine({ ride, myLocation, isLive }) {
  const map = useMap();

  // Refs — we use refs (not state) to avoid re-render loops
  const routeRef              = useRef(null); // current drawn layer group
  const reroutedRef           = useRef(null); // cached off-route OSRM coords
  const lastReroutePos        = useRef(null); // GPS position of last OSRM call
  const isFetchingRef         = useRef(false);// guard against concurrent fetches

  useEffect(() => {
    if (!map || !ride?.routeCoordinates) return;

    // ── 1. Parse the saved OSRM coordinates ──────────────────────────────
    let savedCoords; // [[lat,lng], ...] for Leaflet
    try {
      const raw = typeof ride.routeCoordinates === "string"
        ? JSON.parse(ride.routeCoordinates)
        : ride.routeCoordinates;
      // OSRM stores [lng, lat] — flip to Leaflet's [lat, lng]
      savedCoords = raw.map(pt => [pt[1], pt[0]]);
    } catch (e) {
      console.error("[DynamicRouteLine] Failed to parse routeCoordinates:", e);
      return;
    }

    // ── 2. Non-live / no GPS → draw full saved route ──────────────────────
    if (!isLive || !myLocation?.lat) {
      drawPolyline(map, routeRef, savedCoords);
      return;
    }

    // ── 3. Find the closest point on the saved route to current GPS ───────
    let minDist      = Infinity;
    let closestIndex = 0;
    for (let i = 0; i < savedCoords.length; i++) {
      const d = getDistance(myLocation.lat, myLocation.lng, savedCoords[i][0], savedCoords[i][1]);
      if (d < minDist) { minDist = d; closestIndex = i; }
    }

    // ── 4. ON-ROUTE: trim the saved polyline ──────────────────────────────
    if (minDist <= OFF_ROUTE_THRESHOLD_M) {
      // Clear any cached reroute — we're back on the original path
      reroutedRef.current    = null;
      lastReroutePos.current = null;

      // Slice off everything behind us; add exact GPS as first point for smooth connection
      const trimmed = [
        [myLocation.lat, myLocation.lng],
        ...savedCoords.slice(closestIndex),
      ];
      drawPolyline(map, routeRef, trimmed);
      return;
    }

    // ── 5. OFF-ROUTE: use cached reroute while fetching ───────────────────
    if (reroutedRef.current) {
      // We already have a rerouted path — draw it immediately so map isn't blank
      drawPolyline(map, routeRef, reroutedRef.current);
    }

    // ── 6. OFF-ROUTE: debounce — only call OSRM if moved enough ──────────
    const lastPos = lastReroutePos.current;
    const movedSinceLastReroute = !lastPos
      || getDistance(myLocation.lat, myLocation.lng, lastPos.lat, lastPos.lng) > REROUTE_DEBOUNCE_M;

    if (!movedSinceLastReroute || isFetchingRef.current) return;

    // ── 7. OFF-ROUTE: fetch fresh road route from OSRM ───────────────────
    isFetchingRef.current  = true;
    lastReroutePos.current = { lat: myLocation.lat, lng: myLocation.lng };

    const destLat = ride.destinationLat;
    const destLng = ride.destinationLng;
    const url     = `${OSRM_BASE}/${myLocation.lng},${myLocation.lat};${destLng},${destLat}?overview=full&geometries=geojson`;

    fetch(url)
      .then(r => r.json())
      .then(data => {
        if (data.code === "Ok" && data.routes?.[0]) {
          // Flip [lng,lat] → [lat,lng] for Leaflet
          const newCoords = data.routes[0].geometry.coordinates.map(pt => [pt[1], pt[0]]);
          reroutedRef.current = newCoords;
          drawPolyline(map, routeRef, newCoords);
        }
      })
      .catch(err => {
        console.warn("[DynamicRouteLine] Reroute fetch failed:", err.message);
        // Fallback: draw straight remaining segment so map isn't blank
        const fallback = [
          [myLocation.lat, myLocation.lng],
          ...savedCoords.slice(closestIndex),
        ];
        drawPolyline(map, routeRef, fallback);
      })
      .finally(() => { isFetchingRef.current = false; });

  }, [map, ride?.routeCoordinates, ride?.destinationLat, ride?.destinationLng, isLive, myLocation?.lat, myLocation?.lng]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (routeRef.current) { map?.removeLayer(routeRef.current); }
    };
  }, [map]);

  return null;
}



// ===========================================================================
// MapInternals — all hook-based components inside MapContainer
// ===========================================================================
function MapInternals({ ride, myLocation, isLive, tileLayerRef, activeTileIdx, participants = [], currentUserId = null }) {
  const map = useMap();
  const markerARef = useRef(null);
  const markerBRef = useRef(null);
  const gpsDotRef  = useRef(null);
  const followRef  = useRef(true);
  const riderMarkersRef = useRef({});

  // ── Group Rider Markers ──
  // IMPORTANT: These are draggable demo markers. We ONLY set position on creation.
  // Once created, the user controls position via drag. We never call setLatLng()
  // on existing markers — that causes the "rubber-band" snap-back glitch because
  // React re-renders (from GPS ticks etc.) would push the OLD state position back
  // to the marker while the user is still dragging.
  useEffect(() => {
    if (!map) return;
    
    const currentMarkerIds = new Set();
    
    participants.forEach((p, index) => {
      if (p.userId === currentUserId) return;
      if (!p.lat || !p.lng) return;
      
      const key = String(p.userId); // Use string keys consistently
      currentMarkerIds.add(key);
      
      // Only create NEW markers — never update position of existing ones
      if (!riderMarkersRef.current[key]) {
        const color = p.color || RIDER_COLORS[index % RIDER_COLORS.length];
        const letter = p.avatarLetter || (p.username ? p.username.charAt(0).toUpperCase() : "?");
        const icon = makeRiderIcon(color, letter, p.username || "Rider");
        
        const marker = L.marker([p.lat, p.lng], {
          icon,
          zIndexOffset: 500,
          draggable: true,
          autoPan: false,       // Don't pan map while dragging
        }).addTo(map);
        
        marker.bindPopup(`
          <div style="font-family:system-ui;text-align:center">
            <strong>${p.username || "Rider"}</strong><br/>
            <span style="font-size:11px;color:#666">${p.role === "admin" ? "👑 Admin" : "Rider"}</span>
          </div>
        `);
        
        // On dragend, broadcast the new position so ActiveRideOverlay can track it
        marker.on('dragend', function(event) {
          const position = event.target.getLatLng();
          window.dispatchEvent(new CustomEvent("simulate-group-gps", {
            detail: { userId: p.userId, lat: position.lat, lng: position.lng }
          }));
        });
        
        riderMarkersRef.current[key] = marker;
      }
    });
    
    // Remove markers for participants no longer in the list
    Object.keys(riderMarkersRef.current).forEach(key => {
      if (!currentMarkerIds.has(key)) {
        riderMarkersRef.current[key].remove();
        delete riderMarkersRef.current[key];
      }
    });
    
  }, [map, participants, currentUserId]);

  // Cleanup all rider markers on unmount
  useEffect(() => {
    return () => {
      Object.values(riderMarkersRef.current).forEach(m => m.remove());
      riderMarkersRef.current = {};
    };
  }, []);

  // Store tile layer ref
  useEffect(() => {
    if (!map) return;
    map.eachLayer(l => { if (l instanceof L.TileLayer) tileLayerRef.current = l; });
  }, [map, activeTileIdx]); // re-check when tile changes

  // Stop camera follow on drag
  useEffect(() => {
    if (!map) return;
    const stop = () => { followRef.current = false; };
    map.on("dragstart", stop);
    return () => map.off("dragstart", stop);
  }, [map]);

  // Listen for the custom "re-center" event
  useEffect(() => {
    if (!map) return;
    const handleRecenter = (e) => {
      const { lat, lng } = e.detail;
      followRef.current = true; // Re-enable follow mode
      map.setView([lat, lng], Math.max(map.getZoom(), 16), { animate: true, duration: 0.5 });
    };
    window.addEventListener("rw-recenter", handleRecenter);
    return () => window.removeEventListener("rw-recenter", handleRecenter);
  }, [map]);

  // A marker (start)
  useEffect(() => {
    if (!map || !ride?.fromLat) return;
    const ll   = [ride.fromLat, ride.fromLng];
    const name = (ride.fromName || "Start").split(",")[0];
    if (markerARef.current) {
      markerARef.current.setLatLng(ll);
    } else {
      markerARef.current = L.marker(ll, { icon: ICON_A })
        .addTo(map)
        .bindPopup(`<div style="font-family:system-ui;padding:4px 0;min-width:130px">
          <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">
            <span style="background:#22c55e;color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:12px;font-weight:900">A</span>
            <strong style="color:#111;font-size:14px">${name}</strong>
          </div>
          <span style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:50px;padding:2px 8px;font-size:11px;color:#166534;font-weight:600">
            ${ride.rideType === "solo" ? "🏍️ Solo Ride" : "👥 Group Ride"}
          </span>
        </div>`);
    }
    return () => { markerARef.current?.remove(); markerARef.current = null; };
  }, [map, ride?.fromLat, ride?.fromLng]); // eslint-disable-line

  // B marker (destination)
  useEffect(() => {
    if (!map || !ride?.destinationLat) return;
    const ll   = [ride.destinationLat, ride.destinationLng];
    const name = (ride.destinationName || "Destination").split(",")[0];
    const dist = ride.distanceMeters
      ? ride.distanceMeters >= 1000
        ? (ride.distanceMeters / 1000).toFixed(1) + " km"
        : Math.round(ride.distanceMeters) + " m"
      : "—";
    const eta = ride.durationSeconds
      ? ride.durationSeconds >= 3600
        ? Math.floor(ride.durationSeconds / 3600) + "h " + Math.floor((ride.durationSeconds % 3600) / 60) + "m"
        : Math.round(ride.durationSeconds / 60) + " min"
      : "—";

    if (markerBRef.current) {
      markerBRef.current.setLatLng(ll);
    } else {
      markerBRef.current = L.marker(ll, { icon: ICON_B })
        .addTo(map)
        .bindPopup(`<div style="font-family:system-ui;padding:4px 0;min-width:160px">
          <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">
            <span style="background:#ef4444;color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:12px;font-weight:900">B</span>
            <strong style="color:#111;font-size:14px">${name}</strong>
          </div>
          <div style="display:flex;gap:14px;padding-top:4px;border-top:1px solid #f0f0f0">
            <div style="text-align:center">
              <div style="font-size:16px;font-weight:900;color:#ef4444">${dist}</div>
              <div style="font-size:9px;color:#999;text-transform:uppercase">Distance</div>
            </div>
            <div style="width:1px;background:#f0f0f0"></div>
            <div style="text-align:center">
              <div style="font-size:16px;font-weight:900;color:#333">${eta}</div>
              <div style="font-size:9px;color:#999;text-transform:uppercase">ETA</div>
            </div>
          </div>
        </div>`);
    }
    return () => { markerBRef.current?.remove(); markerBRef.current = null; };
  }, [map, ride?.destinationLat, ride?.destinationLng]); // eslint-disable-line

  // GPS dot (live position)
  useEffect(() => {
    if (!map || !myLocation?.lat) return;
    const ll = [myLocation.lat, myLocation.lng];
       if (gpsDotRef.current) {
      gpsDotRef.current.setLatLng(ll);
    } else {
      gpsDotRef.current = L.marker(ll, { 
        icon: GPS_ICON, 
        zIndexOffset: 1000,
        draggable: true
      })
      .addTo(map)
      .bindPopup("<div style='font-family:system-ui;font-size:13px;font-weight:700'>📍 You are here</div>");
      //this is after line is used for to drag the pointer in the map
      gpsDotRef.current.on('dragend', function(event) {
        const position = event.target.getLatLng();
        window.dispatchEvent(new CustomEvent("simulate-gps", {
          detail: { lat: position.lat, lng: position.lng }
        }));
      });
    }
    if (isLive && followRef.current) {
      map.setView(ll, Math.max(map.getZoom(), 16), { animate: true, duration: 0.5 });
    }
    return () => { gpsDotRef.current?.remove(); gpsDotRef.current = null; };
  }, [map, myLocation?.lat, myLocation?.lng, isLive]); // eslint-disable-line

  return null;
}

// ===========================================================================
// RideMap — exported component (same props as before, no parent changes)
// ===========================================================================
export default function RideMap({ ride, myLocation, isLive = false, participants = [], currentUserId = null }) {
  const tileLayerRef  = useRef(null);
  const [showTiles,   setShowTiles]  = useState(false);
  const [activeTile,  setActiveTile] = useState(0);

  const from = ride?.fromLat        ? { lat: ride.fromLat,        lng: ride.fromLng }        : null;
  const to   = ride?.destinationLat ? { lat: ride.destinationLat, lng: ride.destinationLng } : null;
  const center = from ? [from.lat, from.lng] : [13.0827, 80.2707];

  const switchTile = (i) => {
    setActiveTile(i);
    setShowTiles(false);
    if (tileLayerRef.current) {
      tileLayerRef.current.setUrl(TILE_LAYERS[i].url);
    }
  };

  return (
    <div style={{ position: "absolute", inset: 0 }}>

      <MapContainer
        attributionControl={false /* hides the built-in OpenStreetMap attribution box */}
        center={center}
        zoom={12}
        scrollWheelZoom
        style={{ width: "100%", height: "100%" }}
      >
        <TileLayer
          url={TILE_LAYERS[0].url}
          attribution={TILE_LAYERS[0].attr}
        />

        {/* Dynamic Route line — automatically trims based on myLocation */}
        <DynamicRouteLine ride={ride} myLocation={myLocation} isLive={isLive} />

        {/* Markers + GPS dot + tile ref capture */}
        <MapInternals
          ride={ride}
          myLocation={myLocation}
          isLive={isLive}
          tileLayerRef={tileLayerRef}
          activeTileIdx={activeTile}
          participants={participants}
          currentUserId={currentUserId}
        />
      </MapContainer>

      {/* ── Tile switcher (overlay, outside MapContainer so pointer events work) ── */}
      <div className="rw-custom-control" style={{ position: "absolute", top: "110px", left: "10px", zIndex: 9999 }}>
        <button
          title="Switch map style"
          onClick={() => setShowTiles(v => !v)}
          style={{
            width: "40px", height: "40px", borderRadius: "8px",
            background: "rgba(255,255,255,0.95)",
            border: "2px solid rgba(200,200,200,0.6)",
            boxShadow: "0 2px 8px rgba(0,0,0,0.25)",
            cursor: "pointer", fontSize: "15px",
            display: "flex", alignItems: "center", justifyContent: "center",
          }}
        >🗺️</button>

        {showTiles && (
          <div style={{
            position: "absolute", top: 0, left: "42px",
            background: "rgba(15,15,26,0.96)",
            backdropFilter: "blur(16px)",
            border: "1px solid rgba(255,255,255,0.1)",
            borderRadius: "12px", padding: "4px 0",
            minWidth: "175px",
            boxShadow: "0 4px 24px rgba(0,0,0,0.55)",
          }}>
            {TILE_LAYERS.map((t, i) => (
              <button key={i} onClick={() => switchTile(i)} style={{
                width: "100%", padding: "9px 16px",
                background: "transparent", border: "none",
                borderBottom: i < TILE_LAYERS.length - 1 ? "1px solid rgba(255,255,255,0.06)" : "none",
                color: "white", cursor: "pointer",
                textAlign: "left", fontSize: "13px",
                fontWeight: activeTile === i ? 700 : 400,
                display: "flex", alignItems: "center", gap: "8px",
              }}
              onMouseEnter={e => e.currentTarget.style.background = "rgba(255,255,255,0.07)"}
              onMouseLeave={e => e.currentTarget.style.background = "transparent"}
              >
                <span style={{ flex: 1 }}>{t.label}</span>
                {activeTile === i && <span style={{ color: "#f97316", fontWeight: 900 }}>✓</span>}
              </button>
            ))}
          </div>
        )}
      </div>

         {/* ── Re-center button (live rides only) ── */}
      {isLive && myLocation?.lat && (
        <button
          className="rw-custom-control"
          title="Re-center on your location"
          onClick={() => {
            // Tell locationService to turn off simulation and snap back to real GPS!
            window.dispatchEvent(new Event("resume-real-gps"));
          }}
          style={{
            position: "absolute", bottom: "130px", left: "10px", zIndex: 9999,
            width: "46px", height: "46px", borderRadius: "13px",
            background: "rgba(255,255,255,0.95)",
            border: "2px solid rgba(66,133,244,0.6)",
            color: "#4285F4", cursor: "pointer",
            display: "flex", alignItems: "center", justifyContent: "center",
            fontSize: "18px", boxShadow: "0 2px 16px rgba(0,0,0,0.2)",
          }}
        >
          <i className="fa fa-location-crosshairs" />
        </button>
      )}
    </div>
  );
}

// ============================================================
// 🚀 RideSetupFlow.jsx — Plan a new ride
//
// FLOW (3 steps inside the modal):
//   Step 1: Choose FROM location
//           → Option A: Use current GPS location (green button)
//           → Option B: Type a place name (with suggestions)
//   Step 2: Choose DESTINATION
//           → Type a place name (with autocomplete suggestions)
//   Step 3: Preview route on mini-map → then "Start Ride"
//
// GEOCODING: converts typed text → lat/lng via Nominatim
// ROUTING:   calculates road path via OSRM
// ON START:  calls createRide() → parent receives the new ride object
//
// PROPS:
//   rideType      — "solo" (always, group is future)
//   userId        — logged-in user's ID
//   onRideCreated — callback(ride) when ride is successfully created
//   onCancel      — callback() to go back
//   tc            — theme classes from useTheme()
// ============================================================

import { useState, useCallback } from "react";
import { geocode, getRoute, formatDistance, formatDuration } from "../../../services/routingApi";
import { getCurrentLocation }                                  from "../../../services/locationService";
import { createRide }                                          from "../../../services/rideApi";
import RideMap                                                 from "./RideMap";
import LocationSearchInput                                     from "../shared/LocationSearchInput";

// ---------------------------------------------------------------------------
// Preset popular destinations — shown as quick-pick chips
// Users can also type any custom location
// ---------------------------------------------------------------------------
const POPULAR_PLACES = [
  "Marina Beach, Chennai",
  "Pondicherry",
  "Ooty",
  "Mahabalipuram",
  "Coorg",
  "Goa",
  "Manali",
  "Kodaikanal",
];

// ---------------------------------------------------------------------------
// STEPS enum — which step is currently shown
// ---------------------------------------------------------------------------
const STEP = { FROM: 1, DESTINATION: 2, PREVIEW: 3 };

export default function RideSetupFlow({ rideType, userId, participantIds = [], onRideCreated, onCancel, tc }) {
  // ---- Step tracker ----
  const [step, setStep] = useState(STEP.FROM);

  // ---- FROM location state ----
  const [fromText,        setFromText]        = useState("");   // what the user typed
  const [fromCoords,      setFromCoords]      = useState(null); // { lat, lng, name }
  const [fromSuggestions, setFromSuggestions] = useState([]);  // filtered POPULAR_PLACES
  const [usingGps,        setUsingGps]        = useState(false); // true = GPS used for from

  // ---- DESTINATION state ----
  const [destText,        setDestText]        = useState("");
  const [destCoords,      setDestCoords]      = useState(null);
  const [destSuggestions, setDestSuggestions] = useState([]);

  // ---- Route preview state ----
  const [routeData,  setRouteData]  = useState(null);   // { coordinates, distanceMeters, durationSeconds }
  const [previewRide, setPreviewRide] = useState(null); // fake ride object for RideMap preview

  // ---- Loading / error ----
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState("");

  // ====================================================================
  // FROM — "Use Current Location" button handler
  // ====================================================================

  //THis is the main thing to access the gps of the devcie from browser
  const handleUseGps = async () => {
    setLoading(true);
    setError("");
    try {
      const loc = await getCurrentLocation(); // prompts browser for GPS permission
      setFromCoords({ lat: loc.lat, lng: loc.lng, name: "📍 My Current Location" });
      setFromText("📍 My Current Location");
      setUsingGps(true);
      setFromSuggestions([]);
      // Automatically advance to destination step
      setStep(STEP.DESTINATION);
    } catch (e) {
      setError("Could not get your location. Please allow location access or type an address.");
    } finally {
      setLoading(false);
    }
  };

  // ====================================================================
  // FROM — text input handler (filters suggestions)
  // ====================================================================
  const handleFromType = (text) => {
    setFromText(text);
    setUsingGps(false);
    setFromCoords(null); // clear previous geocoded result when user retypes
    // Filter popular places that contain the typed text (case-insensitive)
    setFromSuggestions(
      text.trim()
        ? POPULAR_PLACES.filter(p => p.toLowerCase().includes(text.toLowerCase()))
        : []
    );
  };

  // User picks a FROM suggestion chip
  const pickFrom = (place) => {
    setFromText(place);
    setFromCoords(null); // will be geocoded when user advances
    setFromSuggestions([]);
  };

  // ====================================================================
  // Advance from Step 1 → Step 2 (geocode the FROM text if needed)
  // ====================================================================
  const handleFromNext = async () => {
    setError("");
    if (!fromText.trim()) { setError("Please enter a starting location."); return; }
    setLoading(true);
    try {
      if (!fromCoords) {
        // Text was typed manually — geocode it
        const result = await geocode(fromText);
        if (!result) throw new Error(`Could not find "${fromText}". Try a more specific name.`);
        setFromCoords(result);
      }
      setStep(STEP.DESTINATION); // go to next step
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  // ====================================================================
  // DESTINATION — text input handler
  // ====================================================================
  const handleDestType = (text) => {
    setDestText(text);
    setDestCoords(null);
    setDestSuggestions(
      text.trim()
        ? POPULAR_PLACES.filter(p => p.toLowerCase().includes(text.toLowerCase()))
        : []
    );
  };

  const pickDest = (place) => {
    setDestText(place);
    setDestCoords(null);
    setDestSuggestions([]);
  };

  // ====================================================================
  // Advance Step 2 → Step 3: geocode destination + calculate route
  // ====================================================================
  const handleCalcRoute = async () => {
    setError("");
    if (!destText.trim()) { setError("Please enter a destination."); return; }
    setLoading(true);
    try {
      // 1. Geocode destination (if not already done)
      let dest = destCoords;
      if (!dest) {
        dest = await geocode(destText);
        if (!dest) throw new Error(`Could not find "${destText}". Try a more specific name.`);
        setDestCoords(dest);
      }

      // 2. Calculate the road route (OSRM)
      const route = await getRoute(fromCoords, dest);
      if (!route) throw new Error("No road route found between these locations.");
      setRouteData(route);

      // 3. Build a fake "ride" object so RideMap can render the preview
      // The route.coordinates array needs to be JSON-stringified (matches DB format)
      setPreviewRide({
        fromLat:         fromCoords.lat,
        fromLng:         fromCoords.lng,
        fromName:        fromCoords.name,
        destinationLat:  dest.lat,
        destinationLng:  dest.lng,
        destinationName: dest.name,
        routeCoordinates: JSON.stringify(route.coordinates), // [[lng,lat], ...]
        routeSteps:       route.steps || [],                 // turn-by-turn steps array
        distanceMeters:   route.distance,
        durationSeconds:  route.duration,
      });

      setStep(STEP.PREVIEW); // show map preview
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  // ====================================================================
  // START RIDE — create the ride in the backend + call onRideCreated
  // ====================================================================
  const handleStartRide = async () => {
    setError("");
    setLoading(true);
    try {
      const dest = destCoords;

      // Build the request body matching our RideRequest DTO
      const ridePayload = {
        userId:           userId,
        fromName:         fromCoords.name,
        fromLat:          fromCoords.lat,
        fromLng:          fromCoords.lng,
        destinationName:  dest.name,
        destinationLat:   dest.lat,
        destinationLng:   dest.lng,
        // Store coordinates as JSON string (our DB column type is TEXT)
        routeCoordinates: JSON.stringify(routeData.coordinates),
        // Store turn-by-turn steps as JSON string for navigation
        routeSteps:       JSON.stringify(routeData.steps || []),
        distanceMeters:   routeData.distance,
        durationSeconds:  routeData.duration,
        rideType:         rideType, // "solo"
        participantIds:   participantIds.length > 0 ? participantIds : undefined,
      };

      // Save to backend (or localStorage fallback)
      const savedRide = await createRide(ridePayload);

      // ── CRITICAL: re-attach route data that backend may not return ──
      // The backend DB might not have a routeCoordinates or routeSteps column,
      // so the returned object may be missing them. We always restore from the
      // locally computed OSRM result so the live map always has coordinates to draw.
      if (!savedRide.routeCoordinates) {
        savedRide.routeCoordinates = JSON.stringify(routeData.coordinates);
      }
      if (!savedRide.routeSteps) {
        savedRide.routeSteps = routeData.steps || [];
      }

      // Tell the parent (Home.jsx) to open the full-screen map for this ride
      onRideCreated(savedRide);

    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  // ====================================================================
  // RENDER
  // ====================================================================
  return (
    <div>
      {/* ---- Step indicator ---- */}
      <div style={{ display: "flex", gap: "6px", marginBottom: "20px" }}>
        {[1, 2, 3].map(n => (
          <div
            key={n}
            style={{
              flex: 1, height: "3px", borderRadius: "2px",
              background: step >= n
                ? "linear-gradient(90deg, #f97316, #ec4899)"   // completed/current = orange
                : "rgba(255,255,255,0.1)",                      // upcoming = faint
              transition: "background 0.3s",
            }}
          />
        ))}
      </div>

      {/* ================================================================
          STEP 1 — FROM LOCATION
      ================================================================ */}
      {step === STEP.FROM && (
        <div className="space-y-3">
          <div>
            <p style={{ fontSize: "11px", fontWeight: 700, opacity: 0.5, textTransform: "uppercase", letterSpacing: "1px", marginBottom: "12px" }}>
              Step 1 of 3 — Where are you starting?
            </p>
          </div>

          {/* Use Current GPS Location button */}
          <button
            onClick={handleUseGps}
            disabled={loading}
            style={{
              width:          "100%",
              padding:        "14px 16px",
              background:     "linear-gradient(135deg, rgba(34,197,94,0.15), rgba(16,185,129,0.1))",
              border:         "1.5px solid rgba(34,197,94,0.4)",
              borderRadius:   "14px",
              display:        "flex",
              alignItems:     "center",
              gap:            "12px",
              cursor:         loading ? "not-allowed" : "pointer",
              color:          "inherit",
              textAlign:      "left",
            }}
          >
            <div style={{
              width: "40px", height: "40px", borderRadius: "12px",
              background: "rgba(34,197,94,0.2)",
              display: "flex", alignItems: "center", justifyContent: "center",
              flexShrink: 0,
            }}>
              <i className="fa fa-location-crosshairs" style={{ color: "#22c55e", fontSize: "18px" }} />
            </div>
            <div>
              <p style={{ fontWeight: 700, margin: 0 }}>Use My Current Location</p>
              <p style={{ fontSize: "12px", opacity: 0.5, margin: 0 }}>Automatically detect via GPS</p>
            </div>
            {loading && <i className="fa fa-spinner fa-spin" style={{ marginLeft: "auto", color: "#22c55e" }} />}
          </button>

          {/* Divider */}
          <div style={{ display: "flex", alignItems: "center", gap: "10px", color: "rgba(255,255,255,0.3)", fontSize: "12px" }}>
            <div style={{ flex: 1, height: "1px", background: "rgba(255,255,255,0.1)" }} />
            or type a location
            <div style={{ flex: 1, height: "1px", background: "rgba(255,255,255,0.1)" }} />
          </div>

          {/* Text input for FROM — live OSM geocoder */}
          <LocationSearchInput
            icon="fa-map-marker-alt"
            iconColor="#22c55e"
            placeholder="Search any city, area, landmark..."
            value={fromText}
            onChange={(text) => { setFromText(text); setUsingGps(false); setFromCoords(null); }}
            onSelect={(result) => {
              setFromText(result.label);
              setFromCoords({ lat: result.lat, lng: result.lng, name: result.label });
            }}
            tc={tc}
          />

          {/* Error */}
          {error && <ErrorBox message={error} />}

          {/* Popular places */}
          <div>
            <p style={{ fontSize: "11px", opacity: 0.4, marginBottom: "8px", textTransform: "uppercase", letterSpacing: "1px" }}>Popular places</p>
            <div style={{ display: "flex", flexWrap: "wrap", gap: "6px" }}>
              {POPULAR_PLACES.slice(0, 6).map(p => (
                <button
                  key={p}
                  onClick={() => pickFrom(p)}
                  style={{
                    padding: "6px 12px", borderRadius: "50px",
                    border: "1px solid rgba(255,255,255,0.12)",
                    background: fromText === p ? "rgba(249,115,22,0.15)" : "rgba(255,255,255,0.04)",
                    borderColor: fromText === p ? "rgba(249,115,22,0.4)" : "rgba(255,255,255,0.12)",
                    color: "inherit", fontSize: "12px", cursor: "pointer", fontWeight: 600,
                  }}
                >
                  {p.split(",")[0]}
                </button>
              ))}
            </div>
          </div>

          {/* Next button */}
          <ActionButton
            label={loading ? "Locating..." : "Next →"}
            icon={loading ? "fa-spinner fa-spin" : "fa-arrow-right"}
            onClick={handleFromNext}
            disabled={loading || !fromText.trim()}
          />

          <CancelButton onClick={onCancel} />
        </div>
      )}

      {/* ================================================================
          STEP 2 — DESTINATION
      ================================================================ */}
      {step === STEP.DESTINATION && (
        <div className="space-y-3">
          <div>
            <p style={{ fontSize: "11px", fontWeight: 700, opacity: 0.5, textTransform: "uppercase", letterSpacing: "1px", marginBottom: "4px" }}>
              Step 2 of 3 — Where are you going?
            </p>
            {/* Show selected FROM as a summary chip */}
            <div style={{
              display: "inline-flex", alignItems: "center", gap: "6px",
              padding: "4px 10px", borderRadius: "50px",
              background: "rgba(34,197,94,0.1)", border: "1px solid rgba(34,197,94,0.2)",
              fontSize: "11px", color: "#22c55e",
            }}>
              <i className="fa fa-location-dot" style={{ fontSize: "10px" }} />
              From: {(fromCoords?.name || fromText).split(",")[0]}
            </div>
          </div>

          {/* Destination input — live OSM geocoder */}
          <LocationSearchInput
            icon="fa-flag-checkered"
            iconColor="#ef4444"
            placeholder="Search destination city, place..."
            value={destText}
            onChange={(text) => { setDestText(text); setDestCoords(null); }}
            onSelect={(result) => {
              setDestText(result.label);
              setDestCoords({ lat: result.lat, lng: result.lng, name: result.label });
            }}
            tc={tc}
          />

          {/* Error */}
          {error && <ErrorBox message={error} />}

          {/* Popular destinations */}
          <div>
            <p style={{ fontSize: "11px", opacity: 0.4, marginBottom: "8px", textTransform: "uppercase", letterSpacing: "1px" }}>Popular destinations</p>
            <div style={{ display: "flex", flexWrap: "wrap", gap: "6px" }}>
              {POPULAR_PLACES.map(p => (
                <button
                  key={p}
                  onClick={() => pickDest(p)}
                  style={{
                    padding: "6px 12px", borderRadius: "50px",
                    border: "1px solid rgba(255,255,255,0.12)",
                    background: destText === p ? "rgba(249,115,22,0.15)" : "rgba(255,255,255,0.04)",
                    borderColor: destText === p ? "rgba(249,115,22,0.4)" : "rgba(255,255,255,0.12)",
                    color: "inherit", fontSize: "12px", cursor: "pointer", fontWeight: 600,
                  }}
                >
                  {p.split(",")[0]}
                </button>
              ))}
            </div>
          </div>

          {/* Back + Calculate Route buttons */}
          <div style={{ display: "flex", gap: "8px" }}>
            <button
              onClick={() => { setStep(STEP.FROM); setError(""); }}
              style={{
                padding: "14px 20px", borderRadius: "14px",
                border: "1px solid rgba(255,255,255,0.12)",
                background: "rgba(255,255,255,0.05)", color: "inherit",
                cursor: "pointer", fontSize: "14px", fontWeight: 600,
              }}
            >
              <i className="fa fa-arrow-left" style={{ marginRight: "6px" }} />
              Back
            </button>
            <ActionButton
              label={loading ? "Calculating..." : "Calculate Route"}
              icon={loading ? "fa-spinner fa-spin" : "fa-route"}
              onClick={handleCalcRoute}
              disabled={loading || !destText.trim()}
              style={{ flex: 1 }}
            />
          </div>
        </div>
      )}

      {/* ================================================================
          STEP 3 — ROUTE PREVIEW + START
      ================================================================ */}
      {step === STEP.PREVIEW && previewRide && (
        <div className="space-y-3">
          <p style={{ fontSize: "11px", fontWeight: 700, opacity: 0.5, textTransform: "uppercase", letterSpacing: "1px" }}>
            Step 3 of 3 — Your Route
          </p>

          {/* Mini map preview */}
          <div style={{ height: "240px", borderRadius: "16px", overflow: "hidden", border: "1px solid rgba(255,255,255,0.1)", position: "relative" }}>
            <RideMap ride={previewRide} isLive={false} />
          </div>

          {/* Route stats */}
          <div style={{
            display: "grid", gridTemplateColumns: "1fr 1fr 1fr 1fr",
            gap: "6px",
          }}>
            {[
              { label: "Distance", value: formatDistance(routeData?.distance), color: "#f97316" },
              { label: "Duration", value: formatDuration(routeData?.duration), color: "#fff" },
              { label: "Turns",    value: String(routeData?.steps?.length || 0), color: "#60a5fa" },
              { label: "Type",     value: rideType,                              color: "#34d399" },
            ].map(({ label, value, color }) => (
              <div
                key={label}
                style={{
                  padding: "10px 8px", borderRadius: "12px",
                  background: "rgba(255,255,255,0.04)",
                  border: "1px solid rgba(255,255,255,0.08)",
                  textAlign: "center",
                }}
              >
                <p style={{ color, fontWeight: 900, fontSize: "14px", margin: 0, textTransform: "capitalize" }}>{value}</p>
                <p style={{ color: "rgba(255,255,255,0.4)", fontSize: "9px", margin: 0, textTransform: "uppercase", letterSpacing: "1px", marginTop: "2px" }}>{label}</p>
              </div>
            ))}
          </div>

          {/* Group Ride Info */}
          {participantIds.length > 0 && (
            <div style={{
              padding: "12px 16px", borderRadius: "12px",
              background: "rgba(255,255,255,0.03)",
              border: "1px solid rgba(255,255,255,0.06)",
              fontSize: "12px",
              display: "flex",
              alignItems: "center",
              gap: "8px",
            }}>
              <p style={{ margin: 0, fontWeight: 700 }}>👥 {participantIds.length + 1} riders</p>
              <p style={{ margin: 0, opacity: 0.5 }}>(including you)</p>
            </div>
          )}

          {/* From → To summary */}
          <div style={{
            padding: "12px 16px", borderRadius: "12px",
            background: "rgba(255,255,255,0.03)",
            border: "1px solid rgba(255,255,255,0.06)",
            fontSize: "12px",
          }}>
            <p style={{ margin: 0 }}>
              <i className="fa fa-circle" style={{ color: "#22c55e", fontSize: "8px", marginRight: "8px" }} />
              {(fromCoords?.name || fromText).split(",")[0]}
            </p>
            <div style={{ margin: "4px 0 4px 4px", borderLeft: "2px dashed rgba(255,255,255,0.1)", height: "10px" }} />
            <p style={{ margin: 0 }}>
              <i className="fa fa-circle" style={{ color: "#ef4444", fontSize: "8px", marginRight: "8px" }} />
              {(destCoords?.name || destText).split(",")[0]}
            </p>
          </div>

          {/* First-step directions preview (first 4 steps) */}
          {routeData?.steps?.length > 0 && (
            <div style={{
              borderRadius: "12px",
              border: "1px solid rgba(255,255,255,0.07)",
              overflow: "hidden",
            }}>
              {/* Header */}
              <div style={{
                display: "flex",
                alignItems: "center",
                gap: "8px",
                padding: "10px 14px",
                background: "rgba(66,133,244,0.08)",
                borderBottom: "1px solid rgba(255,255,255,0.06)",
              }}>
                <i className="fa fa-list" style={{ color: "#4285F4", fontSize: "12px" }} />
                <span style={{ color: "rgba(255,255,255,0.7)", fontSize: "11px", fontWeight: 700 }}>
                  Turn-by-turn preview
                </span>
                <span style={{
                  marginLeft: "auto",
                  background: "rgba(66,133,244,0.2)",
                  color: "#60a5fa",
                  fontSize: "10px",
                  fontWeight: 700,
                  padding: "2px 8px",
                  borderRadius: "50px",
                }}>
                  {routeData.steps.length} steps
                </span>
              </div>

              {/* Step rows (first 4 only) */}
              {routeData.steps.slice(0, 4).map((step, i) => (
                <div
                  key={i}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: "10px",
                    padding: "9px 14px",
                    borderBottom: i < 3 && i < routeData.steps.length - 1
                      ? "1px solid rgba(255,255,255,0.04)"
                      : "none",
                    background: i === 0 ? "rgba(255,255,255,0.03)" : "transparent",
                  }}
                >
                  <div style={{
                    width: "28px",
                    height: "28px",
                    borderRadius: "8px",
                    background: i === 0
                      ? "rgba(66,133,244,0.2)"
                      : "rgba(255,255,255,0.05)",
                    border: `1px solid ${i === 0 ? "rgba(66,133,244,0.35)" : "rgba(255,255,255,0.08)"}`,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    flexShrink: 0,
                  }}>
                    <i
                      className={`fa ${step.icon}`}
                      style={{
                        color:    i === 0 ? "#4285F4" : "rgba(255,255,255,0.4)",
                        fontSize: "11px",
                      }}
                    />
                  </div>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <p style={{
                      color: i === 0 ? "white" : "rgba(255,255,255,0.55)",
                      fontSize: "11px",
                      fontWeight: i === 0 ? 700 : 400,
                      margin: 0,
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                      whiteSpace: "nowrap",
                    }}>
                      {step.instruction}
                    </p>
                  </div>
                  {step.distance > 0 && (
                    <span style={{
                      color: "rgba(255,255,255,0.3)",
                      fontSize: "10px",
                      flexShrink: 0,
                    }}>
                      {formatDistance(step.distance)}
                    </span>
                  )}
                </div>
              ))}

              {/* "... and N more" if steps > 4 */}
              {routeData.steps.length > 4 && (
                <div style={{
                  padding: "8px 14px",
                  color: "rgba(255,255,255,0.3)",
                  fontSize: "10px",
                  textAlign: "center",
                  background: "rgba(255,255,255,0.02)",
                }}>
                  + {routeData.steps.length - 4} more steps (shown during navigation)
                </div>
              )}
            </div>
          )}

          {/* Error */}
          {error && <ErrorBox message={error} />}

          {/* Back + Start Ride buttons */}
          <div style={{ display: "flex", gap: "8px" }}>
            <button
              onClick={() => { setStep(STEP.DESTINATION); setError(""); }}
              style={{
                padding: "14px 20px", borderRadius: "14px",
                border: "1px solid rgba(255,255,255,0.12)",
                background: "rgba(255,255,255,0.05)", color: "inherit",
                cursor: "pointer", fontSize: "14px", fontWeight: 600,
              }}
            >
              <i className="fa fa-arrow-left" style={{ marginRight: "6px" }} />
              Back
            </button>
            <ActionButton
              label={loading ? "Starting..." : "Start Ride!"}
              icon={loading ? "fa-spinner fa-spin" : "fa-motorcycle"}
              onClick={handleStartRide}
              disabled={loading}
              style={{ flex: 1 }}
            />
          </div>
        </div>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// SMALL REUSABLE UI COMPONENTS (local to this file)
// ---------------------------------------------------------------------------

// Primary action button (orange gradient)
function ActionButton({ label, icon, onClick, disabled, style = {} }) {
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      style={{
        padding:       "14px 20px",
        borderRadius:  "14px",
        background:    "linear-gradient(135deg, #f97316, #ec4899)",
        border:        "none",
        color:         "white",
        fontWeight:    900,
        fontSize:      "14px",
        cursor:        disabled ? "not-allowed" : "pointer",
        opacity:       disabled ? 0.5 : 1,
        display:       "flex",
        alignItems:    "center",
        justifyContent: "center",
        gap:           "8px",
        boxShadow:     disabled ? "none" : "0 4px 20px rgba(249,115,22,0.3)",
        transition:    "transform 0.15s, box-shadow 0.15s",
        ...style,
      }}
      onMouseEnter={e => !disabled && (e.currentTarget.style.transform = "scale(1.02)")}
      onMouseLeave={e => (e.currentTarget.style.transform = "scale(1)")}
    >
      <i className={`fa ${icon}`} />
      {label}
    </button>
  );
}

// Cancel link
function CancelButton({ onClick }) {
  return (
    <button
      onClick={onClick}
      style={{
        width: "100%", padding: "10px",
        background: "transparent", border: "none",
        color: "rgba(255,255,255,0.4)", fontSize: "13px",
        cursor: "pointer",
      }}
    >
      Cancel
    </button>
  );
}

// Error message box
function ErrorBox({ message }) {
  return (
    <div style={{
      padding:       "12px 16px",
      borderRadius:  "12px",
      background:    "rgba(239,68,68,0.1)",
      border:        "1px solid rgba(239,68,68,0.3)",
      color:         "#ef4444",
      fontSize:      "13px",
      display:       "flex",
      alignItems:    "flex-start",
      gap:           "8px",
    }}>
      <i className="fa fa-exclamation-circle" style={{ flexShrink: 0, marginTop: "1px" }} />
      {message}
    </div>
  );
}

// ============================================================
// 🏁 StartRideModal.jsx — Slide-up modal for starting/managing rides
//
// SCREENS (internal state machine):
//   "home"    → two big cards: "New Ride" + "Ride History"
//   "type"    → Solo card (active) + Group card (disabled/future)
//   "setup"   → RideSetupFlow (3-step wizard)
//
// This modal does NOT handle the active map.
// When a ride is created here, it calls onRideCreated(ride)
// so Home.jsx can mount the full-screen ActiveRideOverlay.
//
// PROPS:
//   open            — boolean, controls visibility
//   onClose         — called when modal is dismissed
//   tc              — theme classes from useTheme()
//   onRideCreated   — callback(ride) when user starts a new ride
//   onOpenHistory   — callback() to open history panel
// ============================================================

import { useState, useEffect } from "react";
import { useAuth } from "../../../context/AuthContext";
import RideSetupFlow from "../ride/RideSetupFlow";
import { getConnectionsFull } from "../../../services/ridersApi";

// Internal screen names
const SCREEN = {
  HOME:    "home",
  TYPE:    "type",
  RIDERS:  "riders",
  SETUP:   "setup",
};

export default function StartRideModal({ open, onClose, tc, onRideCreated, onOpenHistory }) {
  const { user } = useAuth();

  // Which screen is currently shown inside the modal
  const [screen,   setScreen]   = useState(SCREEN.HOME);
  const [rideType, setRideType] = useState("solo");
  const [friends, setFriends] = useState([]);
  const [selectedRiders, setSelectedRiders] = useState([]);
  const [loadingFriends, setLoadingFriends] = useState(false);

  // Reset to home screen whenever the modal is opened fresh
  useEffect(() => {
    if (open) setScreen(SCREEN.HOME);
  }, [open]);

  // Close on Escape key
  useEffect(() => {
    const handler = e => { if (e.key === "Escape") onClose(); };
    if (open) document.addEventListener("keydown", handler);
    return () => document.removeEventListener("keydown", handler);
  }, [open, onClose]);

  // Handler: ride successfully created in the setup wizard
  const handleRideCreated = (ride) => {
    onClose();                 // close this modal
    onRideCreated(ride);       // tell Home to open the full-screen map
  };

  // Handler: user clicked "Ride History" — open history panel
  const handleHistory = () => {
    onClose();         // close this modal
    onOpenHistory();   // Home.jsx will open the history panel
  };

  if (!open) return null;

  // ---- Header labels per screen ----
  const headerLabel = {
    [SCREEN.HOME]:  { icon: "fa-motorcycle",      title: "RideWise"          },
    [SCREEN.TYPE]:  { icon: "fa-route",            title: "Choose Ride Type"  },
    [SCREEN.RIDERS]: { icon: "fa-user-group", title: "Select Riders" },
    [SCREEN.SETUP]: { icon: "fa-map-location-dot", title: rideType === "solo" ? "Solo Ride Setup" : "Group Ride Setup" },
  }[screen];

  return (
    <>
      {/* ── BACKDROP ──────────────────────────────────────────── */}
      <div
        onClick={e => { if (e.target === e.currentTarget) onClose(); }}
        style={{
          position:       "fixed",
          inset:          0,
          background:     "rgba(0,0,0,0.75)",
          backdropFilter: "blur(8px)",
          zIndex:         8000,
          display:        "flex",
          alignItems:     "flex-end",           // slide up from bottom (mobile-native feel)
          justifyContent: "center",
          padding:        "0 0 0 0",
        }}
      >
        {/* ── MODAL PANEL ───────────────────────────────────────── */}
        <div
          style={{
            width:         "100%",
            maxWidth:      "480px",
            maxHeight:     "90vh",
            background:    "linear-gradient(135deg, rgba(10,10,15,0.98), rgba(15,15,25,0.98))",
            backdropFilter:"blur(24px)",
            borderRadius:  "28px 28px 0 0",   // rounded top corners only (slides from bottom)
            border:        "1px solid rgba(255,255,255,0.08)",
            borderBottom:  "none",
            overflow:      "hidden",
            display:       "flex",
            flexDirection: "column",
            boxShadow:     "0 -20px 80px rgba(0,0,0,0.7)",
            animation:     "slideUp 0.3s cubic-bezier(0.32,0.72,0,1)",
          }}
        >
          {/* ── DRAG HANDLE ─────────────────────────────────────── */}
          {/* Visual hint that this is a bottom sheet */}
          <div style={{
            width: "40px", height: "4px", borderRadius: "2px",
            background: "rgba(255,255,255,0.15)",
            margin: "12px auto 0",
            flexShrink: 0,
          }} />

          {/* ── HEADER ──────────────────────────────────────────── */}
          <div style={{
            display:       "flex",
            alignItems:    "center",
            justifyContent:"space-between",
            padding:       "16px 20px",
            borderBottom:  "1px solid rgba(255,255,255,0.06)",
            flexShrink:    0,
          }}>
            <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
              {/* Back chevron when on type or setup screens */}
              {screen !== SCREEN.HOME && (
                <button
                  onClick={() => {
                    if (screen === SCREEN.SETUP) setScreen(rideType === "group" ? SCREEN.RIDERS : SCREEN.TYPE);
                    else if (screen === SCREEN.RIDERS) setScreen(SCREEN.TYPE);
                    else setScreen(SCREEN.HOME);
                  }}
                  style={{
                    width: "32px", height: "32px", borderRadius: "50%",
                    background: "rgba(255,255,255,0.07)", border: "1px solid rgba(255,255,255,0.1)",
                    color: "rgba(255,255,255,0.8)", cursor: "pointer",
                    display: "flex", alignItems: "center", justifyContent: "center",
                  }}
                >
                  <i className="fa fa-arrow-left" style={{ fontSize: "12px" }} />
                </button>
              )}
              {/* Icon bubble */}
              <div style={{
                width: "38px", height: "38px", borderRadius: "12px",
                background: "linear-gradient(135deg, #f97316, #ec4899)",
                display: "flex", alignItems: "center", justifyContent: "center",
                boxShadow: "0 4px 16px rgba(249,115,22,0.35)",
              }}>
                <i className={`fa ${headerLabel.icon}`} style={{ color: "white", fontSize: "15px" }} />
              </div>
              <span style={{ fontWeight: 900, fontSize: "16px" }}>{headerLabel.title}</span>
            </div>
            {/* X close button */}
            <button
              onClick={onClose}
              style={{
                width: "32px", height: "32px", borderRadius: "50%",
                background: "rgba(255,255,255,0.07)", border: "1px solid rgba(255,255,255,0.1)",
                color: "rgba(255,255,255,0.6)", cursor: "pointer",
                display: "flex", alignItems: "center", justifyContent: "center",
              }}
            >
              <i className="fa fa-times" style={{ fontSize: "13px" }} />
            </button>
          </div>

          {/* ── SCROLLABLE CONTENT ────────────────────────────────── */}
          <div style={{ overflowY: "auto", flex: 1, padding: "20px" }}>

            {/* ================================================
                HOME screen — New Ride + History cards
            ================================================ */}
            {screen === SCREEN.HOME && (
              <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>

                {/* NEW RIDE card */}
                <button
                  onClick={() => setScreen(SCREEN.TYPE)}
                  style={{
                    padding:        "20px",
                    background:     "linear-gradient(135deg, rgba(249,115,22,0.12), rgba(236,72,153,0.08))",
                    border:         "1.5px solid rgba(249,115,22,0.25)",
                    borderRadius:   "20px",
                    display:        "flex",
                    alignItems:     "center",
                    gap:            "16px",
                    cursor:         "pointer",
                    color:          "inherit",
                    textAlign:      "left",
                    width:          "100%",
                    transition:     "transform 0.2s, border-color 0.2s",
                  }}
                  onMouseEnter={e => { e.currentTarget.style.transform = "scale(1.01)"; e.currentTarget.style.borderColor = "rgba(249,115,22,0.5)"; }}
                  onMouseLeave={e => { e.currentTarget.style.transform = "scale(1)";    e.currentTarget.style.borderColor = "rgba(249,115,22,0.25)"; }}
                >
                  <div style={{
                    width: "52px", height: "52px", borderRadius: "16px", flexShrink: 0,
                    background: "linear-gradient(135deg, #f97316, #ec4899)",
                    display: "flex", alignItems: "center", justifyContent: "center",
                    boxShadow: "0 8px 24px rgba(249,115,22,0.35)",
                  }}>
                    <i className="fa fa-motorcycle" style={{ color: "white", fontSize: "22px" }} />
                  </div>
                  <div style={{ flex: 1 }}>
                    <p style={{ fontWeight: 900, fontSize: "16px", margin: "0 0 4px" }}>Start a New Ride</p>
                    <p style={{ fontSize: "12px", color: "rgba(255,255,255,0.45)", margin: 0 }}>
                      Plan your route with geocoding + live map
                    </p>
                  </div>
                  <i className="fa fa-arrow-right" style={{ color: "#f97316", fontSize: "16px" }} />
                </button>

                {/* RIDE HISTORY card */}
                <button
                  onClick={handleHistory}
                  style={{
                    padding:        "20px",
                    background:     "rgba(255,255,255,0.03)",
                    border:         "1px solid rgba(255,255,255,0.08)",
                    borderRadius:   "20px",
                    display:        "flex",
                    alignItems:     "center",
                    gap:            "16px",
                    cursor:         "pointer",
                    color:          "inherit",
                    textAlign:      "left",
                    width:          "100%",
                    transition:     "transform 0.2s, background 0.2s",
                  }}
                  onMouseEnter={e => { e.currentTarget.style.transform = "scale(1.01)"; e.currentTarget.style.background = "rgba(255,255,255,0.06)"; }}
                  onMouseLeave={e => { e.currentTarget.style.transform = "scale(1)";    e.currentTarget.style.background = "rgba(255,255,255,0.03)"; }}
                >
                  <div style={{
                    width: "52px", height: "52px", borderRadius: "16px", flexShrink: 0,
                    background: "rgba(255,255,255,0.07)",
                    border: "1px solid rgba(255,255,255,0.1)",
                    display: "flex", alignItems: "center", justifyContent: "center",
                  }}>
                    <i className="fa fa-clock-rotate-left" style={{ color: "rgba(255,255,255,0.6)", fontSize: "20px" }} />
                  </div>
                  <div style={{ flex: 1 }}>
                    <p style={{ fontWeight: 900, fontSize: "16px", margin: "0 0 4px" }}>Ride History</p>
                    <p style={{ fontSize: "12px", color: "rgba(255,255,255,0.45)", margin: 0 }}>
                      View, reopen or delete past rides
                    </p>
                  </div>
                  <i className="fa fa-arrow-right" style={{ color: "rgba(255,255,255,0.3)", fontSize: "16px" }} />
                </button>
              </div>
            )}

            {/* ================================================
                TYPE screen — Solo or Group
            ================================================ */}
            {screen === SCREEN.TYPE && (
              <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
                <p style={{ fontSize: "12px", color: "rgba(255,255,255,0.4)", margin: "0 0 4px" }}>
                  How are you riding today?
                </p>

                {/* SOLO — active */}
                <button
                  onClick={() => { setRideType("solo"); setScreen(SCREEN.SETUP); }}
                  style={{
                    padding:      "20px",
                    background:   "linear-gradient(135deg, rgba(249,115,22,0.1), rgba(234,179,8,0.08))",
                    border:       "1.5px solid rgba(249,115,22,0.3)",
                    borderRadius: "20px",
                    display:      "flex",
                    alignItems:   "center",
                    gap:          "16px",
                    cursor:       "pointer",
                    color:        "inherit",
                    textAlign:    "left",
                    width:        "100%",
                    transition:   "transform 0.2s",
                  }}
                  onMouseEnter={e => e.currentTarget.style.transform = "scale(1.01)"}
                  onMouseLeave={e => e.currentTarget.style.transform = "scale(1)"}
                >
                  <div style={{
                    width: "52px", height: "52px", borderRadius: "16px", flexShrink: 0,
                    background: "linear-gradient(135deg, #f97316, #ca8a04)",
                    display: "flex", alignItems: "center", justifyContent: "center",
                    fontSize: "24px",
                  }}>
                    🏍️
                  </div>
                  <div style={{ flex: 1 }}>
                    <p style={{ fontWeight: 900, fontSize: "16px", color: "#fb923c", margin: "0 0 4px" }}>Solo Ride</p>
                    <p style={{ fontSize: "12px", color: "rgba(255,255,255,0.45)", margin: 0 }}>
                      Just you. Plan your route and hit the road.
                    </p>
                  </div>
                  <i className="fa fa-arrow-right" style={{ color: "#f97316" }} />
                </button>

                {/* GROUP — active */}
                <button
                  onClick={() => {
                    setRideType("group");
                    setSelectedRiders([]);
                    setLoadingFriends(true);
                    getConnectionsFull(user?.id).then(list => {
                      setFriends(list || []);
                      setLoadingFriends(false);
                    }).catch(() => { setFriends([]); setLoadingFriends(false); });
                    setScreen(SCREEN.RIDERS);
                  }}
                  style={{
                    padding:      "20px",
                    background:   "linear-gradient(135deg, rgba(139,92,246,0.1), rgba(99,102,241,0.08))",
                    border:       "1.5px solid rgba(139,92,246,0.3)",
                    borderRadius: "20px",
                    display:      "flex",
                    alignItems:   "center",
                    gap:          "16px",
                    cursor:       "pointer",
                    color:        "inherit",
                    textAlign:    "left",
                    width:        "100%",
                    transition:   "transform 0.2s",
                  }}
                  onMouseEnter={e => e.currentTarget.style.transform = "scale(1.01)"}
                  onMouseLeave={e => e.currentTarget.style.transform = "scale(1)"}
                >
                  <div style={{
                    width: "52px", height: "52px", borderRadius: "16px", flexShrink: 0,
                    background: "linear-gradient(135deg, #8b5cf6, #6366f1)",
                    display: "flex", alignItems: "center", justifyContent: "center",
                    fontSize: "24px",
                  }}>
                    👥
                  </div>
                  <div style={{ flex: 1 }}>
                    <p style={{ fontWeight: 900, fontSize: "16px", color: "#8b5cf6", margin: "0 0 4px" }}>Group Ride</p>
                    <p style={{ fontSize: "12px", color: "rgba(255,255,255,0.45)", margin: 0 }}>
                      Ride with friends. Live map for all members.
                    </p>
                  </div>
                  <i className="fa fa-arrow-right" style={{ color: "#8b5cf6" }} />
                </button>
              </div>
            )}

            {/* ================================================
                RIDERS screen — Select friends for group ride
            ================================================ */}
            {screen === SCREEN.RIDERS && (
              <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
                {/* Header text */}
                <p style={{ fontSize: "12px", color: "rgba(255,255,255,0.4)", margin: "0 0 4px" }}>
                  Choose friends to ride with ({selectedRiders.length} selected)
                </p>

                {/* Loading state */}
                {loadingFriends && (
                  <div style={{ textAlign: "center", padding: "32px 0", color: "rgba(255,255,255,0.4)" }}>
                    <i className="fa fa-spinner fa-spin" style={{ fontSize: "24px", marginBottom: "8px" }} />
                    <p style={{ fontSize: "13px" }}>Loading your friends...</p>
                  </div>
                )}

                {/* No friends state */}
                {!loadingFriends && friends.length === 0 && (
                  <div style={{
                    textAlign: "center", padding: "32px 16px",
                    background: "rgba(255,255,255,0.03)",
                    border: "1px solid rgba(255,255,255,0.08)",
                    borderRadius: "16px",
                  }}>
                    <div style={{ fontSize: "40px", marginBottom: "12px" }}>👥</div>
                    <p style={{ fontWeight: 700, fontSize: "15px", margin: "0 0 8px" }}>No Friends Yet</p>
                    <p style={{ fontSize: "12px", color: "rgba(255,255,255,0.4)", margin: "0 0 16px" }}>
                      Add friends first to create a group ride
                    </p>
                    <button
                      onClick={() => { onClose(); window.location.href = "/riders"; }}
                      style={{
                        padding: "10px 24px",
                        background: "linear-gradient(135deg, #8b5cf6, #6366f1)",
                        border: "none", borderRadius: "12px",
                        color: "white", fontWeight: 700, fontSize: "13px",
                        cursor: "pointer",
                        boxShadow: "0 4px 16px rgba(139,92,246,0.4)",
                      }}
                    >
                      <i className="fa fa-user-plus" style={{ marginRight: "8px" }} />
                      Go to Riders
                    </button>
                  </div>
                )}

                {/* Friends list with checkboxes */}
                {!loadingFriends && friends.length > 0 && (
                  <>
                    {/* Select all toggle */}
                    <button
                      onClick={() => {
                        if (selectedRiders.length === friends.length) setSelectedRiders([]);
                        else setSelectedRiders(friends.map(f => f.id));
                      }}
                      style={{
                        padding: "8px 14px",
                        background: selectedRiders.length === friends.length
                          ? "rgba(139,92,246,0.15)" : "rgba(255,255,255,0.04)",
                        border: `1px solid ${selectedRiders.length === friends.length
                          ? "rgba(139,92,246,0.4)" : "rgba(255,255,255,0.08)"}`,
                        borderRadius: "10px",
                        color: "rgba(255,255,255,0.7)", fontSize: "12px", fontWeight: 600,
                        cursor: "pointer", textAlign: "left",
                      }}
                    >
                      <i className={`fa ${selectedRiders.length === friends.length ? "fa-check-square" : "fa-square"}`}
                        style={{ marginRight: "8px", color: selectedRiders.length === friends.length ? "#8b5cf6" : "rgba(255,255,255,0.3)" }} />
                      {selectedRiders.length === friends.length ? "Deselect All" : "Select All"}
                    </button>

                    {/* Individual friend cards */}
                    <div style={{ display: "flex", flexDirection: "column", gap: "6px", maxHeight: "280px", overflowY: "auto" }}>
                      {friends.map(friend => {
                        const isSelected = selectedRiders.includes(friend.id);
                        return (
                          <button
                            key={friend.id}
                            onClick={() => {
                              setSelectedRiders(prev =>
                                isSelected ? prev.filter(id => id !== friend.id) : [...prev, friend.id]
                              );
                            }}
                            style={{
                              padding: "12px 14px",
                              background: isSelected ? "rgba(139,92,246,0.12)" : "rgba(255,255,255,0.03)",
                              border: `1.5px solid ${isSelected ? "rgba(139,92,246,0.4)" : "rgba(255,255,255,0.06)"}`,
                              borderRadius: "14px",
                              display: "flex", alignItems: "center", gap: "12px",
                              cursor: "pointer", color: "inherit", textAlign: "left", width: "100%",
                              transition: "all 0.2s",
                            }}
                          >
                            {/* Checkbox */}
                            <div style={{
                              width: "22px", height: "22px", borderRadius: "6px", flexShrink: 0,
                              background: isSelected ? "linear-gradient(135deg, #8b5cf6, #6366f1)" : "rgba(255,255,255,0.06)",
                              border: isSelected ? "none" : "1.5px solid rgba(255,255,255,0.15)",
                              display: "flex", alignItems: "center", justifyContent: "center",
                            }}>
                              {isSelected && <i className="fa fa-check" style={{ color: "white", fontSize: "11px" }} />}
                            </div>

                            {/* Avatar */}
                            <div style={{
                              width: "36px", height: "36px", borderRadius: "50%", flexShrink: 0,
                              background: "linear-gradient(135deg, #8b5cf6, #6366f1)",
                              display: "flex", alignItems: "center", justifyContent: "center",
                              color: "white", fontWeight: 900, fontSize: "14px",
                            }}>
                              {(friend.username || friend.email || "?")[0].toUpperCase()}
                            </div>

                            {/* Info */}
                            <div style={{ flex: 1, minWidth: 0 }}>
                              <p style={{ fontWeight: 700, fontSize: "14px", margin: "0 0 2px",
                                overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                                {friend.username || "Rider"}
                              </p>
                              <p style={{ fontSize: "11px", color: "rgba(255,255,255,0.35)", margin: 0,
                                overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                                {friend.email}
                              </p>
                            </div>
                          </button>
                        );
                      })}
                    </div>

                    {/* Next button */}
                    <button
                      onClick={() => setScreen(SCREEN.SETUP)}
                      disabled={selectedRiders.length === 0}
                      style={{
                        padding: "14px",
                        background: selectedRiders.length > 0
                          ? "linear-gradient(135deg, #8b5cf6, #6366f1)" : "rgba(255,255,255,0.06)",
                        border: "none", borderRadius: "14px",
                        color: selectedRiders.length > 0 ? "white" : "rgba(255,255,255,0.3)",
                        fontWeight: 900, fontSize: "15px",
                        cursor: selectedRiders.length > 0 ? "pointer" : "not-allowed",
                        boxShadow: selectedRiders.length > 0 ? "0 4px 20px rgba(139,92,246,0.4)" : "none",
                        transition: "all 0.2s",
                      }}
                    >
                      <i className="fa fa-arrow-right" style={{ marginRight: "8px" }} />
                      Continue with {selectedRiders.length} Rider{selectedRiders.length !== 1 ? "s" : ""}
                    </button>
                  </>
                )}
              </div>
            )}

            {/* ================================================
                SETUP screen — 3-step wizard
            ================================================ */}
            {screen === SCREEN.SETUP && (
              <RideSetupFlow
                rideType={rideType}
                userId={user?.id}
                participantIds={rideType === "group" ? selectedRiders : []}
                onRideCreated={handleRideCreated}
                onCancel={() => setScreen(rideType === "group" ? SCREEN.RIDERS : SCREEN.TYPE)}
                tc={tc}
              />
            )}

          </div>
        </div>
      </div>

      {/* Slide-up animation keyframe */}
      <style>{`
        @keyframes slideUp {
          from { transform: translateY(100%); }
          to   { transform: translateY(0); }
        }
      `}</style>
    </>
  );
}

// ============================================================
// 🎤 useVoice HOOK — Voice command recognition
// ============================================================

import { useState, useCallback, useEffect } from "react";

export function useVoice(commands = {}) {
  const [voiceMode, setVoiceMode] = useState(false);
  const [recognition, setRecognition] = useState(null);

  const startVoice = useCallback(() => {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Voice not supported on this browser. Try Chrome or Edge.");
      return;
    }

    const rec = new SpeechRecognition();
    rec.lang = "en-US";
    rec.continuous = false;
    rec.interimResults = false;

    rec.onresult = (event) => {
      const text = event.results[0][0].transcript.toLowerCase().trim();
      console.log("🎤 Heard:", text);

      for (const [keyword, fn] of Object.entries(commands)) {
        if (text.includes(keyword)) {
          fn();
          break;
        }
      }
    };

    rec.onend = () => setVoiceMode(false);
    rec.onerror = () => setVoiceMode(false);

    rec.start();
    setRecognition(rec);
    setVoiceMode(true);

    // Auto-stop after 6 seconds
    setTimeout(() => {
      try { rec.stop(); } catch (e) { /* already stopped */ }
      setVoiceMode(false);
    }, 6000);
  }, [commands]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (recognition) {
        try { recognition.stop(); } catch (_) {}
      }
    };
  }, [recognition]);

  return {
    voiceMode,
    startVoice,
    voiceSupported: !!(window.SpeechRecognition || window.webkitSpeechRecognition),
  };
}

// ============================================================
// 📍 useRideLocation — React hook for live rider location
//
// Uses locationService.watchLocation() under the hood.
// When the component unmounts, location tracking stops automatically.
//
// Usage:
//   const { location, error, isWatching } = useRideLocation(active);
//
// active = true  → starts watching
// active = false → stops watching
// ============================================================

import { useState, useEffect } from "react";
import { watchLocation } from "../../services/locationService";

export function useRideLocation(active = true) {
  const [location,   setLocation]   = useState(null);
  const [error,      setError]      = useState(null);
  const [isWatching, setIsWatching] = useState(false);

  useEffect(() => {
    if (!active) return;

    setIsWatching(true);
    
    // Start watching; the cleanup function stops it.
    // onError is now wired — previously GPS failures (denied permission,
    // timeout, unavailable) never surfaced because the callback was
    // never passed, so `error` stayed null forever.
    const stop = watchLocation(
      (loc) => {
        setLocation(loc);
        setError(null);
      },
      (err) => setError(err?.message || "Unable to get your location")
    );

    // Cleanup when component unmounts or active changes to false
    return () => {
      stop();
      setIsWatching(false);
    };
  }, [active]);

  return { location, error, isWatching };
}

